var PROJECTS=[{"year": "2026", "title": "Display (Node e.V.)", "jahr": "2026", "ort": "Frankfurt", "art": "Ausstellungsarchitektur", "desc": "Konzeption, Projektsteuerung und Möbelentwurf für Display, einen Raum für digitale Praxis im Zentrum von Frankfurt", "text": ["Display ist ein Raum für digitale Praxis in der Frankfurter Innenstadt, eingerichtet in einem ehemals leerstehenden Ladenlokal. Betrieben wird er von NODE e.V. im Auftrag und in Kooperation mit der Stabsstelle Digitalisierung der Stadt Frankfurt. Der Raum versteht sich als begehbarer Screen und Interface, Experimentierlabor und Community-Space und wurde am 18. Februar 2026 eröffnet. YRD.Works waren 2025 und 2026 für Konzeption und Projektsteuerung zuständig und haben das Möbelsystem entworfen. Der Raum sollte als Werkstatt, Veranstaltungsort und offene Anlaufstelle funktionieren. Das Konzept hat deshalb eine feste Grundstruktur, die viele Varianten zulässt.", "Ausgangspunkt war das Raster. Es ordnet die Module und ihre Kombinationen und verweist auf digitale Systeme, in denen Bedeutung aus der Anordnung kleinster Einheiten entsteht. Vorbilder wie OpenStructures, die Lochkarte und der Märklin-Metallbaukasten stehen für diese Verwandtschaft. Das Raster verbindet so die analoge Werkstatt mit den digitalen Inhalten und gibt dem Raum eine Ordnung, ohne ihn festzulegen.", "Umgesetzt ist das Konzept als Baukasten aus gelochten Holzleisten. Ein einheitliches Raster aus 9-mm-Löchern im Abstand von 5 cm zieht sich durch alle Möbel und Raumelemente: Regale, eine ausziehbare Tribüne, die im Regal verschwindet und sich bei Bedarf zu einer Treppenlandschaft öffnet, modulare Flex Desks zum Einhängen in die Leisten, ein Tiny Makerspace und eine zentrale Bar. Alle Teile lassen sich erweitern, umbauen oder neu zusammensetzen. Zwischen den drei Hauptnutzungen des Raums, Event, Co-Create und Workshop, wechselt man durch das Verschieben weniger Module. Im Untergeschoss liegen Archiv und Medienlager, ein Open Lab und ein Rückzugsraum.", "Das Schaufenster zum Kornmarkt gibt den Blick in den Raum frei, der so für die Straße zur Bühne wird. Daher kommt der Titel: Display meint die digitale Anzeige, das Schaufenster und den Raum, der seine eigene Arbeit ausstellt.", "Farbe und Licht folgen demselben System. Verkehrsblau (RAL 5017) und Verkehrsgrün (RAL 6024) ziehen sich durch alle Module und machen sie unabhängig vom Möbeltyp als zusammengehörig erkennbar. Eine dimmbare, tageslichtnahe Grundbeleuchtung bildet die Basis. An sie lassen sich modulare Leuchten andocken, je nach Nutzung als Arbeitslicht am Tag oder als Akzent- und Veranstaltungslicht am Abend.", "Der Raum ist darauf angelegt, mit seiner Nutzung zu wachsen. Das Raster bleibt als Grundordnung, die Möbel lassen sich verändern, und das Schaufenster zeigt nach außen, was drinnen passiert."], "gallery": [["Bilder/2026-display/01.webp", 1497, 1000], ["Bilder/2026-display/02.webp", 1498, 1000], ["Bilder/2026-display/03.webp", 1498, 1000], ["Bilder/2026-display/04.webp", 668, 1000], ["Bilder/2026-display/05.webp", 668, 1000], ["Bilder/2026-display/06.webp", 1500, 1000], ["Bilder/2026-display/07.webp", 1499, 1000], ["Bilder/2026-display/08.webp", 1499, 1000]], "text_en": ["Display is a space for digital practice in Frankfurt's city centre, set up in a formerly vacant shop. It is run by NODE e.V. on behalf of and in cooperation with the City of Frankfurt's Digitalisation Unit. The space describes itself as a walk-in screen and interface, experimental lab and community space, and it opened on 18 February 2026. YRD.Works were responsible for the concept and project management in 2025 and 2026 and designed the furniture system. The room had to work as a workshop, a venue and an open point of contact, so the concept has a fixed underlying structure that allows for many variations.", "The starting point was the grid. It organises the modules and their combinations and refers to digital systems in which meaning comes from the arrangement of the smallest units. References such as OpenStructures, the punch card and the Märklin metal construction kit stand for this kinship. The grid connects the analogue workshop with the digital content and gives the room an order without fixing it.", "The concept was realised as a construction kit of perforated timber battens. A uniform grid of 9 mm holes at 5 cm spacing runs through all furniture and spatial elements: shelving, an extendable grandstand that disappears into the shelving and opens into a landscape of steps when needed, modular flex desks that hook into the battens, a tiny makerspace and a central bar. All parts can be extended, rebuilt or recombined. Moving a few modules switches the room between its three main uses: event, co-create and workshop. The basement holds an archive and media store, an open lab and a retreat room.", "The shop window facing Kornmarkt opens the view into the room, which becomes a stage for the street. This is where the title comes from: Display means the digital screen, the shop window and the room that exhibits its own work.", "Colour and light follow the same system. Traffic blue (RAL 5017) and traffic green (RAL 6024) run through all modules and make them recognisable as one family regardless of furniture type. Dimmable base lighting close to daylight forms the basis. Modular lights can dock onto it, as task lighting during the day or as accent and event lighting in the evening, depending on use.", "The room is designed to grow with its use. The grid remains as the underlying order, the furniture can be changed, and the shop window shows the outside what happens inside."], "fotos": "Eda Temuçin"}, {"year": "2025", "title": "Bingenheim", "jahr": "2025", "ort": "Bingenheim / Wetterau", "art": "Rauminstallation", "desc": "Entwicklung und Umsetzung einer begehbaren Skulptur in einem Dachstuhl einer alten Scheune, die als unkonventioneller Ausstellungsraum von einem Kunstverein genutzt wird", "text": ["2025 haben YRD.Works in der Tenne einer alten Hofscheune in Bingenheim (Wetterau) eine begehbare Rauminstallation gebaut. Die Scheune gehört dem Verein WetterAussicht e.V., der in einer Region mit wenigen Ausstellungs- und Veranstaltungsorten kulturelle Infrastruktur aufbaut. Der Verein hatte YRD.Works offen zu einer Kooperation eingeladen, ohne Ort oder Format vorzugeben. Die Idee entstand bei der ersten Begehung der Scheune und ging vom alten Dachstuhl aus.", "Die Arbeit ist Skulptur und Ausstellungsraum in einem. Sie steht als eigenständiger Einbau im Bestand und dient dem Verein dauerhaft als Raum für sein Programm. Beides war von Anfang an gleich wichtig.", "In den offenen Dachstuhl ist eine schmale, längliche Kammer eingehängt. Ein Holzständerwerk mit glatt verputzten Gipsflächen bildet innen einen geschlossenen weißen Raum. Die Konstruktion nutzt tragende Punkte des alten Dachstuhls mit, Bestand und Einbau sind also baulich miteinander verbunden. Eine offene Treppe in der Längsachse der Scheune führt hinauf. Die Decke ist als Lichtdecke gebaut: Zwei große Leuchtfelder, wie man sie aus Museen kennt, geben gleichmäßiges, schattenfreies Licht. So bleibt der Innenraum unabhängig vom wechselnden Tageslicht der Scheune.", "In der Kammer ist von der alten Scheune nichts mehr zu sehen. Im Dachraum dunkle Balken, Bruchsteinwände und offene Konstruktion, in der Kammer glatte weiße Wände, scharfe Kanten und überall dasselbe Licht. Vom Dachraum aus ist die Kammer als eigener Baukörper zu erkennen.", "Mit der Kammer kommt der klassische Ausstellungsraum in ein landwirtschaftliches Gebäude, ohne dass die Scheune ihren Charakter verliert. Sie soll bleiben und dem Verein auch nach dem Projekt als Ausstellungsort dienen."], "gallery": [["Bilder/2025-bingenheim/01.webp", 1498, 1000], ["Bilder/2025-bingenheim/02.webp", 1498, 1000], ["Bilder/2025-bingenheim/03.webp", 668, 1000], ["Bilder/2025-bingenheim/04.webp", 1498, 1000], ["Bilder/2025-bingenheim/05.webp", 668, 1000], ["Bilder/2025-bingenheim/06.webp", 1498, 1000], ["Bilder/2025-bingenheim/07.webp", 1498, 1000], ["Bilder/2025-bingenheim/08.webp", 1542, 1000], ["Bilder/2025-bingenheim/09.webp", 668, 1000], ["Bilder/2025-bingenheim/10.webp", 1498, 1000], ["Bilder/2025-bingenheim/11.webp", 1498, 1000]], "text_en": ["In 2025, YRD.Works built a walk-in spatial installation in the threshing floor of an old farm barn in Bingenheim, Wetterau. The barn belongs to WetterAussicht e.V., an association building cultural infrastructure in a region with few exhibition and event spaces. The association had invited YRD.Works to collaborate without specifying a site or format. The idea came up during a first visit to the barn and started from the old roof truss.", "The work is a sculpture and an exhibition space in one. It stands on its own as an insertion into the existing building and gives the association a permanent venue for its programme. Both roles mattered equally from the start.", "A narrow, elongated chamber hangs in the open roof truss. A timber stud frame with smoothly plastered gypsum surfaces encloses a white interior. The construction uses load-bearing points of the old truss, so the existing structure and the insertion are physically connected. An open staircase along the barn's long axis leads up to it. The ceiling is built as a light ceiling: two large light panels of the kind used in museums give an even, shadowless light and keep the interior independent of the barn's changing daylight.", "Inside the chamber, nothing of the old barn is visible. In the roof space there are dark beams, rubble-stone walls and exposed construction; in the chamber there are smooth white walls, sharp edges and the same light everywhere. From the roof space, the chamber can be seen as a separate volume.", "The chamber brings the conventional exhibition space into an agricultural building without the barn losing its character. It is meant to stay and serve the association as an exhibition venue beyond the project."], "kachel": "11_hero_angepasst.jpg", "img": "Bilder/2025-bingenheim/hero.webp", "fotos": "Gabriel Poblete"}, {"year": "2024", "title": "Transition 1-7", "jahr": "2024", "ort": "Offenbach", "art": "Rauminstallation / Aktion / Performance", "desc": "Sieben Veranstaltungen auf einer Skulptur, die bei jedem Event auf einem anderen Teil des Geländes installiert und mit einer Drohne dokumentiert wurde", "text": ["Transition 1-7 war ein temporäres Kunstprojekt von YRD.Works, das sich 2024 mit der Transformation des Offenbacher Hafengeländes für den zukünftigen Neubau der Hochschule für Gestaltung auseinandersetzte. Seit 2016 hatte das Kollektiv das Gelände in einer mehrjährigen Zwischennutzung mit Kulturveranstaltungen und Ausstellungen bespielt, vor allem in der von ihm betriebenen Kressmann-Halle. Mit dem bevorstehenden Neubau zeichneten sich das Ende dieser Aktivitäten und ein radikaler baulicher Umbruch ab.", "YRD.Works thematisierten diesen Umbruch in sieben experimentellen, öffentlichen Lehrveranstaltungen, eingebunden in die Lehre von Heiner Blum an der HfG. Workshops, Vorträge und Panels mit eingeladenen Expert*innen blickten zurück auf das Geschehene und voraus auf die Zukunft des Areals. Räumlicher Träger war eine skulpturale Plattform aus angedeuteten Fertighaus-Wandteilen, die wie beiläufig auf Lagerhölzern zwischengelagert wirkten. Im Zwei-Wochen-Takt wanderte sie an sieben Standorte des Geländes, und für jede Veranstaltung wurden die Wandteile neu arrangiert.", "An jeder Station wurde die Plattform per Drohne aus der Vogelperspektive fotografiert, und durch die veränderte Anordnung der Wandteile entstand jedes Mal ein neues Bild. Die sieben Aufnahmen wurden zu einer Gesamtansicht des Geländes montiert, in der die Skulptur an allen Standorten gleichzeitig zu sehen ist. Transition 1-7 ist so der Versuch, einen Übergang herzustellen, bei dem sich Vergangenheit und Zukunft sinnbildlich überlappen."], "gallery": [["Bilder/2024-transition-1-7/01.webp", 1333, 1000], ["Bilder/2024-transition-1-7/02.webp", 1500, 1000], ["Bilder/2024-transition-1-7/03.webp", 1333, 1000], ["Bilder/2024-transition-1-7/04.webp", 1500, 1000], ["Bilder/2024-transition-1-7/05.webp", 1333, 1000], ["Bilder/2024-transition-1-7/06.webp", 1499, 1000], ["Bilder/2024-transition-1-7/07.webp", 1333, 1000], ["Bilder/2024-transition-1-7/08.webp", 1500, 1000], ["Bilder/2024-transition-1-7/09.webp", 1333, 1000], ["Bilder/2024-transition-1-7/10.webp", 1500, 1000], ["Bilder/2024-transition-1-7/11.webp", 1333, 1000]], "text_en": ["Transition 1-7 was a temporary art project by YRD.Works that in 2024 addressed the transformation of the Offenbach harbour site for the future new building of the Hochschule für Gestaltung (HfG). Since 2016, the collective had used the site in a multi-year interim use for cultural events and exhibitions, above all in the Kressmann-Halle, which it ran. With the upcoming new building, the end of these activities and a radical structural upheaval were becoming apparent.", "YRD.Works addressed this upheaval in seven experimental, public teaching events, embedded in Heiner Blum's teaching at the HfG. Workshops, talks and panels with invited experts looked back at what had happened and ahead to the future of the site. The spatial vehicle was a sculptural platform made of suggested prefabricated-house wall elements that appeared to have been casually put into storage on timber bearers. Every two weeks it moved to one of seven locations on the site, and the wall elements were rearranged for each event.", "At each station the platform was photographed from above by drone, and the changed arrangement of the wall elements produced a new image each time. The seven images were assembled into an overall view of the site in which the sculpture can be seen at all locations simultaneously. Transition 1-7 is thus an attempt to create a transition in which past and future symbolically overlap."], "fotos": "Gabriel Poblete · Vlada Shcholkina · YRD.Works"}, {"year": "2024", "title": "Im Angesicht des Todes", "jahr": "2024", "ort": "Frankfurt", "art": "Ausstellungsarchitektur", "desc": "Entwicklung einer immersiven Ausstellungsarchitektur für eine siebenmonatige Ausstellung zum Thema Tod im Jüdischen Museum Frankfurt", "text": ["2024 haben YRD.Works die Architektur für die Ausstellung Im Angesicht des Todes im Jüdischen Museum Frankfurt umgesetzt. Die Wechselausstellung über das Sterben in der jüdischen Erzähltradition lief etwa sieben Monate auf rund 600 m². YRD.Works hatten schon 2023 bei einem anderen Ausstellungsprojekt mit dem Museum zusammengearbeitet. Daraus ergab sich der Auftrag, neben der Gestaltung eine eigene künstlerische Position einzubringen, die sich auf das Thema bezieht und so selbst zum Inhalt der Ausstellung gehört.", "Am Anfang stand die Entscheidung, die naheliegende Bildwelt zum Tod nicht zu verwenden: kein Schwarz als Trauerfarbe, keine Verdunkelung, keine Schwere. Im Mittelpunkt steht stattdessen das Unbegreifliche am Tod, übersetzt in einen hellen Lichtraum ohne klare Grenzen. Dem Licht steht Lehm gegenüber, ein irdisches, organisches Material, das für Vergänglichkeit, Wärme und Körperlichkeit steht. Der Lehm verweist außerdem auf den Umgang mit Ressourcen, ohne dass der Raum das erklärt.", "Wände und Decken sind durchgehend mit erdbrauner Lehmfarbe gestrichen, der Boden bleibt heller Sichtbeton. Schmale Lichtkanten in den Anschlüssen von Wand und Decke gliedern die Raumfolge und bilden die einzige Lichtführung. Zur Ausstattung gehören braun lasierte Holztafeln mit gefräster zweisprachiger Schrift, kleine gerahmte Schwarz-Weiß-Drucke, schwarze Stahlrahmenvitrinen mit ritueller Kleidung aus weißem Leinen, eine von oben beleuchtete Tüchertafel vor einer Wandnische, ein heller, fichtenfarbener Holzsarg auf dem Boden, schmale schwarze Sitzbänke, ein Bildschirm an der Wand und schwarze Wandvitrinen mit Objekten aus Papier und Textil.", "Die Architektur musste zwei Dinge leisten. Sie sollte sehr unterschiedliche Exponate aufnehmen, ohne sie zu dominieren: Kunstobjekte, Einzelstücke, Alltagsgegenstände, lichtempfindliche Papierdrucke und interaktive Medienstationen. Und sie sollte deutlich genug sein, um als eigene Arbeit erkennbar zu bleiben. YRD.Works lösten das mit einer reduzierten, einfarbigen Hülle, die die Vielfalt der Exponate zulässt, ohne sie zu kommentieren.", "Die Ausstellung vermittelte ihr Thema vor allem über Informationen, die sich an den Kopf richten. Die Architektur fügte eine Ebene hinzu, die man im Raum körperlich erfährt. Es ging ihr weniger um Trauer als um ein unbestimmtes Gefühl für das Unfassbare am Tod, das sich beim Aufenthalt in den Räumen einstellt."], "gallery": [["Bilder/2024-im-angesicht-des-todes/01.webp", 1333, 1000], ["Bilder/2024-im-angesicht-des-todes/02.webp", 1334, 1000], ["Bilder/2024-im-angesicht-des-todes/03.webp", 1500, 1000], ["Bilder/2024-im-angesicht-des-todes/04.webp", 1333, 1000], ["Bilder/2024-im-angesicht-des-todes/05.webp", 1503, 1000], ["Bilder/2024-im-angesicht-des-todes/06.webp", 1503, 1000]], "text_en": ["In 2024, YRD.Works realised the architecture for the exhibition Im Angesicht des Todes (In the Face of Death) at the Jewish Museum Frankfurt. The temporary exhibition on dying in the Jewish narrative tradition ran for about seven months on around 600 m². YRD.Works had already worked with the museum on another exhibition project in 2023. This led to a brief to contribute, alongside the design, an artistic position of their own that relates to the theme and thus becomes part of the exhibition's content.", "The work began with the decision not to use the obvious imagery of death: no black as the colour of mourning, no darkness, no heaviness. Instead, the focus is on what is incomprehensible about death, translated into a bright space of light without clear boundaries. The light is set against clay, an earthly, organic material that stands for transience, warmth and physical presence. The clay also points to the use of resources, without the space explaining it.", "Walls and ceilings are painted throughout in earth-brown clay paint, while the floor remains light exposed concrete. Narrow light edges in the junctions between wall and ceiling structure the sequence of rooms and form the only lighting. The furnishings include brown-glazed timber panels with milled bilingual lettering, small framed black-and-white prints, black steel-framed showcases with ritual garments of white linen, a cloth panel lit from above in front of a wall niche, a pale spruce-coloured wooden coffin on the floor, narrow black benches, a wall-mounted screen and black wall showcases with paper and textile objects.", "The architecture had to do two things. It was to accommodate very different exhibits without dominating them: art objects, unique pieces, everyday items, light-sensitive paper prints and interactive media stations. And it had to be distinct enough to remain recognisable as a work in its own right. YRD.Works solved this with a reduced, monochrome shell that allows for the diversity of the exhibits without commenting on it.", "The exhibition conveyed its subject mainly through information addressed to the mind. The architecture added a level that visitors experience physically in the space. It was less about grief than about a vague sense of what is incomprehensible about death, one that sets in while spending time in the rooms."], "fotos": "Gabriel Poblete · Norbert Niguletz"}, {"year": "2023", "title": "Tables", "jahr": "2023", "ort": "Offenbach", "art": "Rauminstallation / Aktion", "desc": "Multimediales Projekt, bei dem das Restaurant Emma Metzler mehrere Gänge gekocht hat und dabei von YRD.Works auf abstrakte Weise porträtiert wurde", "text": ["Tables wurde 2023 von YRD.Works als Auftragswerk für das Restaurant Emma Metzler in Offenbach konzipiert und in Zusammenarbeit mit der Belegschaft des Restaurants umgesetzt. Die Arbeit ist ein Hybrid aus Fotografie und Aktion, die in einer wechselseitigen Beziehung zueinander stehen.", "Für das Projekt wurde zunächst eine 8,40 m lange Tafel von YRD.Works konstruiert, die Platz für alle Mitarbeitenden des Restaurants bot. Das gesamte Team von Emma Metzler bereitete für die Aktion unterschiedliche, farblich aufeinander abgestimmte Gerichte zu, die anschließend in mehreren Gängen serviert wurden. Im Stil eines Personalessens wurde dann gemeinsam an der langen Tafel gegessen, getrunken und gefeiert.", "Über dem Tisch wurde eine Stahlschiene mit einer motorisierten Kameravorrichtung von YRD.Works installiert. Mithilfe dieser speziellen Apparatur, die an einen Scanner erinnerte, konnte die gesamte Tischoberfläche in 42 aufeinanderfolgenden, hochauflösenden Fotos im Originalmaßstab abgebildet werden. Die resultierenden Fotografien dokumentieren die sechs wechselnden Tischsituationen der Aktion und porträtieren auf abstrakte Weise das Restaurant Emma Metzler. Insgesamt sind 252 Fotografien, aus 42 Kamerapositionen und sechs Szenen, miteinander kombinierbar, was eine scheinbar endlose Zahl an Variationen des Bilds im Gastraum des Restaurants ermöglicht."], "img": "Bilder/2023-tables/hero.webp", "nocrop": true, "gallery": [["Bilder/2023-tables/01.webp", 6999, 1000], ["Bilder/2023-tables/05.webp", 6999, 1000], ["Bilder/2023-tables/02.webp", 6999, 1000], ["Bilder/2023-tables/04.webp", 6999, 1000], ["Bilder/2023-tables/03.webp", 6999, 1000], ["Bilder/2023-tables/06.webp", 6999, 1000]], "text_en": ["Tables was conceived by YRD.Works in 2023 as a commission for the restaurant Emma Metzler in Offenbach and realised in collaboration with the restaurant's staff. The work is a hybrid of photography and action, the two standing in a reciprocal relationship.", "For the project, YRD.Works first built an 8.40 m long table with room for all of the restaurant's staff. The entire Emma Metzler team prepared a range of dishes coordinated by colour for the action, which were then served in several courses. In the manner of a staff meal, everyone then ate, drank and celebrated together at the long table.", "Above the table, YRD.Works installed a steel rail with a motorised camera rig. Using this special apparatus, reminiscent of a scanner, the entire table surface could be captured at original scale in 42 consecutive high-resolution photographs. The resulting images document the six changing table situations of the action and portray the Emma Metzler restaurant in an abstract way. In total, 252 photographs from 42 camera positions and six scenes can be combined with one another, allowing a seemingly endless number of variations of the image in the restaurant's dining room."], "fotos": "YRD.Works"}, {"year": "2023", "title": "Hole/Mound", "jahr": "2023", "ort": "Roldisleben / Thüringen", "art": "Rauminstallation / Aktion", "desc": "Partizipatives Kunstprojekt, bei dem zwei Pavillons mit unterschiedlichen Funktionen auf einem Feld in Thüringen errichtet wurden", "img": "Bilder/2023-hole-mound/hero.webp", "text": ["Das Thüringer Becken gehört zu den ältesten Kulturlandschaften Deutschlands. Seine fruchtbaren Böden haben seit Jahrtausenden Menschen angezogen, sie spielen eine wichtige Rolle in der Siedlungsgeschichte und sind die Basis für die Landwirtschaft in der Region. Gleichzeitig sieht sich Thüringen heute mit neuen Herausforderungen konfrontiert: Landflucht, schwindendes Vertrauen in die Demokratie und radikale politische Tendenzen gefährden zunehmend das soziale Gefüge. Vor diesem Hintergrund entwickelten YRD.Works 2023 die partizipative Kunstaktion und temporäre Intervention Hole/Mound auf einem Gerstenfeld im thüringischen Roldisleben.", "Im Zentrum der Arbeit standen zwei von YRD.Works errichtete, 6 m hohe Holzpavillons, die auf einem Hügel oberhalb des Dorfes positioniert schon von weitem sichtbar waren. Ein industrielles Förderband verband die beiden 5 m voneinander entfernten baugleichen Pavillons. Sie schienen einander zu spiegeln, unterschieden sich aber in ihrer kontrastierenden Farbgestaltung und vor allem durch ihre Funktion: Der schwarze Pavillon fungierte als Grabungsstätte, während der weiße Pavillon als Ausstellungsfläche diente.", "Die Besucher*innen konnten Teil von Hole/Mound werden und sich aktiv in die auf drei Monate angelegte Aktion einbringen. Mit Spaten, Schaufeln und Pickeln gruben sie in der Mitte des schwarzen Pavillons ein immer tiefer werdendes Loch und schaufelten den Erdaushub auf das mechanische Förderband. Dieses transportierte die Erde in den weißen Pavillon, wo sie in die Raummitte fiel und im Verlauf der drei Monate einen stetig wachsenden Hügel bildete.", "Während das Loch im schwarzen Pavillon mit jeder gegrabenen Schaufel tiefer wurde, wuchs der Hügel im weißen Pavillon kontinuierlich in die Höhe. Durch diese wechselseitige Dynamik erzeugte Hole/Mound zwei gegensätzliche, sich aber bedingende Formen, die u. a. das kollektive Handeln aller Besucher*innen über die Dauer eines Sommers hinweg visualisierten."], "gallery": [["Bilder/2023-hole-mound/01.webp", 1499, 1000], ["Bilder/2023-hole-mound/02.webp", 668, 1000], ["Bilder/2023-hole-mound/03.webp", 668, 1000], ["Bilder/2023-hole-mound/04.webp", 1499, 1000], ["Bilder/2023-hole-mound/05.webp", 668, 1000], ["Bilder/2023-hole-mound/06.webp", 1499, 1000], ["Bilder/2023-hole-mound/07.webp", 667, 1000], ["Bilder/2023-hole-mound/08.webp", 667, 1000], ["Bilder/2023-hole-mound/09.webp", 1499, 1000], ["Bilder/2023-hole-mound/10.webp", 1499, 1000], ["Bilder/2023-hole-mound/11.webp", 1499, 1000], ["Bilder/2023-hole-mound/12.webp", 668, 1000]], "text_en": ["The Thuringian Basin is one of the oldest cultural landscapes in Germany. Its fertile soils have attracted people for millennia; they have played an important role in the history of settlement and are the basis of the region's agriculture. At the same time, Thuringia today faces new challenges: rural exodus, declining trust in democracy and radical political tendencies increasingly threaten the social fabric. Against this background, in 2023 YRD.Works developed the participatory art action and temporary intervention Hole/Mound on a barley field in Roldisleben, Thuringia.", "At the centre of the work were two 6 m high timber pavilions built by YRD.Works, which, positioned on a hill above the village, were visible from afar. An industrial conveyor belt connected the two identical pavilions, standing 5 m apart. They seemed to mirror each other but differed in their contrasting colour and above all in their function: the black pavilion served as a dig site, the white one as an exhibition space.", "Visitors could become part of Hole/Mound and actively contribute to the action, which was planned to last three months. With spades, shovels and pickaxes, they dug an ever-deepening hole in the middle of the black pavilion and shovelled the excavated soil onto the mechanical conveyor belt. This carried the earth into the white pavilion, where it fell into the centre of the room and, over the three months, formed a steadily growing mound.", "While the hole in the black pavilion grew deeper with every shovelful, the mound in the white pavilion rose continuously. Through this reciprocal dynamic, Hole/Mound produced two opposing yet mutually dependent forms that, among other things, visualised the collective action of all visitors over the course of a summer."], "kachel": "06_3-2.jpg", "fotos": "Gabriel Poblete"}, {"year": "2023", "title": "Soups", "jahr": "2023", "ort": "Offenbach", "art": "Rauminstallation / Aktion", "desc": "Partizipatives Kunstprojekt, bei dem mit 15 Initiativen und Vereinen Suppe gekocht wurde, die unentgeltlich an die Besuchenden ausgegeben wurde", "text": ["Suppen als universelles und in vielen Länderküchen verankertes Gericht waren Inspiration für das partizipative Kunstprojekt Soups. YRD.Works konzipierten und realisierten das Projekt im Auftrag der Stadt Offenbach im Rathaus-Pavillon, einem zum Zeitpunkt der Aktion leerstehenden Gebäude im Zentrum der Stadt. Für das Projekt schuf das Künstlerkollektiv eine temporäre Architektur, die sowohl als Küche als auch als Gastraum diente. Die Rauminstallation bestand aus mehreren Küchenelementen, einem eigens für das Projekt gefertigten, raumgreifenden Sitzmöbel und einem großen, zentral im Raum platzierten, 100 Liter fassenden Suppentopf.", "Die Küche, bestehend aus vier mobilen Arbeitsstationen aus Edelstahl, ermöglichte tagsüber professionelles Kochen. Abends wurden die Küchenelemente beiseitegeschoben, um den Raum für das gemeinsame Essen zu öffnen. Der Suppentopf, der das Zentrum der Installation bildete, wurde unter einem gezielt platzierten Spot inszeniert. Dieser war die einzige Lichtquelle innerhalb des schwarz gestrichenen Raums, wodurch der Fokus unweigerlich auf den Topf als zentralen Punkt der Architektur gelenkt wurde. Die rund um den Topf angeordnete Installation erlaubte es allen Gästen, gemeinsam auf dem Möbel und im gleichen Abstand zum Topf in der Raummitte zu sitzen.", "Über einen Zeitraum von fünf Wochen luden die Künstler zu insgesamt 15 Veranstaltungen verschiedene Akteur*innen aus Offenbacher Initiativen und Gruppen ein, gemeinsam mit ihnen eine Suppe nach ihren persönlichen Rezepten zu kochen. So entstanden 15 Suppengerichte aus diversen (Herkunfts-)Ländern und Kulturen der Mitwirkenden. Pro Gericht wurden zwischen 150 und 200 Portionen von den Köch*innen unentgeltlich an die Besucher*innen ausgegeben und dann gemeinsam verzehrt.", "Soups entwickelte sich über die Dauer der Aktion zu einem wiederkehrenden Ritual, das sowohl den verbindenden Prozess des gemeinsamen Kochens als auch die gemeinschaftliche Nutzung des innerstädtischen Raumes in den Vordergrund stellte. Der Rathaus-Pavillon wurde zu einem sozialen Treffpunkt und einem Ort des Austauschs. Das gemeinschaftliche Kochen der Suppe in einem großen Topf stellte dabei eine symbolische Verbindung zwischen allen teilnehmenden Offenbacher*innen her. Soups war ein Projekt, das die Vielfalt, aber auch die Einheit einer heterogenen Stadtgesellschaft sichtbar machte."], "gallery": [["Bilder/2023-soups/01.webp", 1500, 1000], ["Bilder/2023-soups/02.webp", 667, 1000], ["Bilder/2023-soups/03.webp", 757, 1000], ["Bilder/2023-soups/04.webp", 1500, 1000], ["Bilder/2023-soups/05.webp", 1500, 1000], ["Bilder/2023-soups/06.webp", 1500, 1000], ["Bilder/2023-soups/07.webp", 1500, 1000], ["Bilder/2023-soups/08.webp", 1500, 1000], ["Bilder/2023-soups/09.webp", 1500, 1000], ["Bilder/2023-soups/10.webp", 1500, 1000]], "text_en": ["Soup, a universal dish rooted in many national cuisines, was the inspiration for the participatory art project Soups. YRD.Works conceived and realised the project on behalf of the City of Offenbach in the Rathaus-Pavillon, a building in the city centre that was vacant at the time. For the project, the collective created a temporary architecture that served as both kitchen and dining room. The spatial installation consisted of several kitchen elements, a large seating structure made specially for the project, and a big 100-litre soup pot placed at the centre of the room.", "The kitchen, made up of four mobile stainless-steel workstations, allowed for professional cooking during the day. In the evenings, the kitchen elements were pushed aside to open the room for eating together. The soup pot at the heart of the installation was staged under a precisely placed spotlight. This was the only source of light in the black-painted room, inevitably drawing attention to the pot as the focal point of the architecture. The installation arranged around the pot allowed all guests to sit together on the furniture, each at the same distance from the pot in the middle of the room.", "Over a period of five weeks, the artists invited various actors from Offenbach initiatives and groups to a total of 15 events to cook a soup together according to their personal recipes. The result was 15 soups from the diverse countries (of origin) and cultures of the participants. For each dish, the cooks handed out between 150 and 200 portions free of charge to visitors, and everyone then ate together.", "Over the course of the action, Soups developed into a recurring ritual that foregrounded both the connecting process of cooking together and the shared use of inner-city space. The Rathaus-Pavillon became a social meeting point and a place of exchange. Cooking the soup together in one large pot created a symbolic connection between all participating Offenbach residents. Soups was a project that made visible the diversity, but also the unity, of a heterogeneous urban society."], "fotos": "Gabriel Poblete"}, {"year": "2022", "title": "Steady Burn", "jahr": "2022", "ort": "Offenbach", "art": "Skulptur / Aktion / Livestream", "desc": "Livestream einer Aktion, bei der über einen Zeitraum von mehreren Tagen eine Holzplattform verbrannt wird und sich die ursprüngliche Skulptur wortwörtlich aufbraucht", "text": ["Für das Projekt Steady Burn war von YRD.Works auf einem ehemaligen Industriegelände in Offenbach eine 18 × 10 m große, begehbare Holzplattform errichtet worden. Diese wurde in einem mehrtägigen Prozess von den Künstlern und den an dem Projekt teilnehmenden Besucher*innen zersägt und in einer mitten auf der Plattform installierten Feuerstelle verbrannt. Das Objekt verbrauchte sich dabei selbst: Der über 89 Stunden dauernde Prozess endete erst, als von der Plattform nur mehr die glühende Feuerstelle übrig blieb.", "Während des gesamten Zeitraums wurde das Feuer von den Künstlern sowie von den an der Aktion Teilnehmenden gemeinsam unterhalten. Besonders nachts erforderte die Aufrechterhaltung des Feuers eine gewisse Organisation, da sich die Anwesenden abwechselnd um die Feuerstelle kümmerten und dafür sorgten, dass stetig neues Holz nachgelegt wurde, um das Feuer am Brennen zu halten.", "Indem die Teilnehmenden der Aktion sich um das Feuer versammelten, kochten und übernachteten, wurde es zum wärmenden Zentrum des sozialen Miteinanders. Auf der anderen Seite stand seine zerstörerische Kraft, die sich in der Vernichtung der Plattform offenbarte.", "Eine weitere wichtige Ebene des Projekts war die visuelle Darstellung der Aktion durch einen Livestream. Vier über der Plattform installierte Kameras filmten das Geschehen über den gesamten Zeitraum aus der Vogelperspektive und streamten es auf eine speziell dafür eingerichtete Website. Zu sehen war ein vierteiliges, sich langsam veränderndes Polyptychon: Zu Beginn der Aktion füllte die Plattform die vier Bildausschnitte vollständig aus. Im Laufe der Aktion schrumpfte diese jedoch immer mehr, sodass immer größere Teile des Bodens sichtbar wurden. Steady Burn erzeugte ein dynamisches Bild einer Skulptur, die ihre eigene Endlichkeit fortwährend thematisierte."], "gallery": [["Bilder/2022-steady-burn/01.webp", 1778, 1000], ["Bilder/2022-steady-burn/02.webp", 1778, 1000], ["Bilder/2022-steady-burn/03.webp", 1778, 1000], ["Bilder/2022-steady-burn/04.webp", 1778, 1000], ["Bilder/2022-steady-burn/05.webp", 1778, 1000], ["Bilder/2022-steady-burn/06.webp", 1778, 1000], ["Bilder/2022-steady-burn/07.webp", 1778, 1000], ["Bilder/2022-steady-burn/08.webp", 1778, 1000], ["Bilder/2022-steady-burn/09.webp", 1778, 1000], ["Bilder/2022-steady-burn/10.webp", 1778, 1000], ["Bilder/2022-steady-burn/11.webp", 1778, 1000], ["Bilder/2022-steady-burn/12.webp", 1778, 1000], ["Bilder/2022-steady-burn/13.webp", 1778, 1000], ["Bilder/2022-steady-burn/14.webp", 1778, 1000], ["Bilder/2022-steady-burn/15.webp", 1778, 1000]], "text_en": ["For the project Steady Burn, YRD.Works built an 18 × 10 m walk-in timber platform on a former industrial site in Offenbach. Over several days, the artists and the visitors taking part in the project sawed it apart and burned it in a fire pit installed in the middle of the platform. In the process, the object consumed itself: the burn, lasting more than 89 hours, only ended when nothing remained of the platform but the glowing fire pit.", "Throughout the entire period, the fire was kept going jointly by the artists and the participants. At night in particular, keeping the fire alive required some organisation, as those present took turns tending the fire pit and making sure that fresh wood was constantly added to keep it burning.", "As the participants gathered around the fire, cooked and slept there, it became the warming centre of social togetherness. On the other side stood its destructive force, revealed in the destruction of the platform.", "Another important level of the project was the visual representation of the action through a live stream. Four cameras installed above the platform filmed the events from a bird's-eye view throughout the entire period and streamed them to a dedicated website. What could be seen was a four-part, slowly changing polyptych: at the beginning of the action, the platform completely filled the four frames. As the action progressed, however, it shrank more and more, revealing ever larger parts of the ground. Steady Burn produced a dynamic image of a sculpture that continuously addressed its own finitude."], "kachel": "SB_36_1.tiff", "img": "Bilder/2022-steady-burn/hero.webp", "fotos": "Stills: YRD.Works"}, {"year": "2022", "title": "Forschungswerkstatt", "jahr": "2022", "ort": "Frankfurt", "art": "Ausstellungsarchitektur", "desc": "Werkstatt für Kinder und Jugendliche als Teil der Dauerausstellung in einem Naturkundemuseum", "text": ["2022 haben YRD.Works im Senckenberg Naturmuseum Frankfurt die Architektur der Aha?! Forschungswerkstatt umgesetzt. Die Werkstatt ist ein fester Raum für Vermittlung, Workshops und Sammlungsarbeit und liegt im ehemaligen Pausenraum im Untergeschoss des Museums. Das Museum hatte YRD.Works 2021 angefragt, ein bestehendes pädagogisches Konzept räumlich weiterzuführen und den Raum als eigene künstlerische Arbeit zu entwerfen.", "Der Raum sollte Wissenschaftler*innen und Publikum zusammenbringen: Besucher*innen sollten sehen, wie geforscht wird, und Expert*innen direkt fragen können. Außerdem musste er für konzentrierte Arbeit, offene Workshops und Veranstaltungen gleichermaßen taugen. Der Bestand war schwierig: niedrige Decken, Betonsäulen, wenig Tageslicht. Der Entwurf geht von genau diesen Bedingungen aus.", "Zentrales Element ist ein großes Sammlungsregal aus fünf rollbaren Elementen. Es verweist auf die wissenschaftlichen Sammlungen von Senckenberg, die der Öffentlichkeit sonst verschlossen sind. Verschiebt man die Regale, entstehen unterschiedliche Raumsituationen, die Grundordnung des Raums bleibt dabei erhalten. An den Längsseiten liegen hell beleuchtete Arbeitsnischen wie in einem Labor, in denen Mikroskope, Bücher und originale Sammlungsobjekte nebeneinanderstehen. In die Wände ist ein French-Cleat-System eingebaut: Eine Keilleiste sitzt fest an der Wand, eine zweite an wechselnden Einbauten wie Magnetwänden oder Vitrinen. So lassen sich die Wandflächen jederzeit neu belegen.", "Zwischen Sammlungsregalen und Arbeitsnischen läuft ein dunkler, tiefblauer Umgang, der dem niedrigen Raum Ruhe gibt. Die hellen Arbeitszonen und die dunkelblaue Hülle ergeben eine konzentrierte und trotzdem geborgene Atmosphäre. Von einer Sitztribüne aus können Eltern zusehen, wie ihre Kinder an den Mikroskopen arbeiten oder die Forschungsboxen mit Originalen aus der Sammlung durchsuchen. Besucher*innen machen so selbst mit oder schauen zu.", "Die Forschungswerkstatt funktioniert seitdem ohne ständige Erklärung. Sammlungsregal, Arbeitsnischen, Tribüne und Umgang lassen sich für Forschung, Vermittlung oder einfach zum Verweilen nutzen. Sammlung und Labor, sonst hinter den Kulissen des Museums, sind hier öffentlich zugänglich."], "gallery": [["Bilder/2022-forschungswerkstatt/01.webp", 1503, 1000], ["Bilder/2022-forschungswerkstatt/02.webp", 1503, 1000], ["Bilder/2022-forschungswerkstatt/03.webp", 1503, 1000], ["Bilder/2022-forschungswerkstatt/04.webp", 1503, 1000], ["Bilder/2022-forschungswerkstatt/05.webp", 666, 1000]], "text_en": ["In 2022, YRD.Works realised the architecture of the Aha?! Forschungswerkstatt (Research Workshop) at the Senckenberg Nature Museum Frankfurt. The workshop is a permanent space for education, workshops and collection work, located in the museum's former staff break room in the basement. The museum had approached YRD.Works in 2021 to develop an existing educational concept further in spatial terms and to design the room as an artistic work in its own right.", "The room was meant to bring scientists and the public together: visitors should be able to see how research is done and ask experts directly. It also had to work equally well for focused work, open workshops and events. The existing space was difficult: low ceilings, concrete columns, little daylight. The design starts from exactly these conditions.", "The central element is a large collection shelf made of five mobile units. It refers to Senckenberg's scientific collections, which are normally closed to the public. Moving the shelves creates different spatial situations while the basic order of the room stays intact. Along the long sides are brightly lit work niches, like those in a laboratory, where microscopes, books and original collection objects stand side by side. A French cleat system is built into the walls: one bevelled batten is fixed to the wall, a second one to changing fittings such as magnetic boards or showcases. This means the wall surfaces can be rearranged at any time.", "Between the collection shelves and the work niches runs a dark, deep blue walkway that gives the low room a sense of calm. The bright work zones and the dark blue shell create an atmosphere that is focused and still sheltering. From a seating platform, parents can watch their children working at the microscopes or searching through research boxes with original specimens from the collection. Visitors can take part themselves or watch.", "Since then, the Forschungswerkstatt has worked without constant explanation. Collection shelf, work niches, seating platform and walkway can be used for research, education or simply spending time. Collection and laboratory, usually behind the scenes of the museum, are open to the public here."], "fotos": "Gabriel Poblete"}, {"year": "2021", "title": "Current Tours", "jahr": "2021", "ort": "Hannover", "art": "Rauminstallation / Aktion", "desc": "Bootstouren, die mit einem experimentellen Audioguide begleitet werden, in einer schwimmenden Skulptur in den Herrenhäuser Gärten in Hannover", "text": ["Im Mai 2021 präsentierten YRD.Works im Rahmen der KunstFestSpiele Herrenhausen in Hannover die partizipative Arbeit Current Tours. Mit dem Projekt knüpfte das Künstlerkollektiv an eine aristokratische Tradition an, die bereits im frühen 18. Jahrhundert in den Herrenhäuser Gärten gepflegt wurde. Damals wurden Gondelfahrten als höfisches Vergnügen auf der Graft angeboten, einem etwa 2 km langen Kanal, der die Herrenhäuser Gärten umschließt.", "Mit Current Tours ließen YRD.Works diese Tradition wieder aufleben: Sie bauten ein 12 × 4 m großes Floß, das durch einen fast lautlosen Elektromotor angetrieben wurde. Auf dem Floß konnten bis zu zwölf Personen gleichzeitig eine etwa 40-minütige Fahrt auf dem Kanal genießen. Die Passagiere saßen während der Fahrt in kleinen Kabinen, die zu zwei Seiten zum Ufer hin geöffnet waren. Die Fahrten fanden während der KunstFestSpiele mehrmals täglich statt und wurden von den Künstlern begleitet, die das Floß selbst steuerten. Zusätzlich zu den regulären Fahrten gab es besondere Touren in der Nacht und im Morgengrauen.", "Die langsamen Floßfahrten eröffneten neue Perspektiven auf die Herrenhäuser Gärten, indem durch die sich stetig und fast unbemerkt verschiebenden Sichtachsen neue Blicke auf die strenge Geometrie der barocken Gartenlandschaft ermöglicht wurden.", "In Anlehnung an Audioguides von Sightseeing-Touren gab es an Bord des Floßes Kopfhörer, über die das Publikum während der Fahrt einer experimentellen Soundcollage lauschen konnte. Das generative Hörstück wurde von YRD.Works in Zusammenarbeit mit dem Komponisten und Hörspielautor Oliver Augst produziert. Die Collage, bestehend aus fragmentierten musikalischen Beiträgen von Charlotte Simon und Elias Gottstein sowie einer Vielzahl im Internet gesammelter O-Töne, arrangierte sich bei jeder Fahrt neu durch einen von Augst entwickelten Algorithmus. Inhaltlich bezog sich das Hörstück auf die zunehmende Komplexität globaler Finanzsysteme, die selbst Expert*innen längst nicht mehr vollständig durchdringen.", "Die fortwährende Neukombination der Tonfragmente erzeugte vielschichtige Bezüge, die ironische Kommentare auf die fragmentierte Wahrnehmung moderner Finanzsysteme schufen und gleichzeitig deren Widersprüche und Dynamiken reflektierten."], "gallery": [["Bilder/2022-current-tours/01.webp", 1501, 1000], ["Bilder/2022-current-tours/02.webp", 1496, 1000], ["Bilder/2022-current-tours/03.webp", 665, 1000], ["Bilder/2022-current-tours/04.webp", 667, 1000], ["Bilder/2022-current-tours/05.webp", 665, 1000], ["Bilder/2022-current-tours/06.webp", 667, 1000], ["Bilder/2022-current-tours/07.webp", 667, 1000], ["Bilder/2022-current-tours/08.webp", 1313, 1000]], "text_en": ["In May 2021, YRD.Works presented the participatory work Current Tours as part of KunstFestSpiele Herrenhausen in Hanover. With the project, the collective took up an aristocratic tradition cultivated in the Herrenhausen Gardens as early as the early 18th century. Back then, gondola rides were offered as a courtly amusement on the Graft, a canal around 2 km long that encloses the gardens.", "With Current Tours, YRD.Works revived this tradition: they built a 12 × 4 m raft powered by an almost silent electric motor. Up to twelve people at a time could enjoy a roughly 40-minute trip along the canal. During the trip, passengers sat in small cabins that were open on two sides towards the banks. The trips took place several times a day during the festival and were accompanied by the artists, who steered the raft themselves. In addition to the regular trips, there were special tours at night and at dawn.", "The slow raft rides opened up new perspectives on the Herrenhausen Gardens, as the constantly and almost imperceptibly shifting sightlines allowed new views of the strict geometry of the baroque garden landscape.", "Borrowing from the audio guides of sightseeing tours, headphones on board allowed the audience to listen to an experimental sound collage during the trip. The generative audio piece was produced by YRD.Works in collaboration with the composer and radio play author Oliver Augst. The collage, consisting of fragmented musical contributions by Charlotte Simon and Elias Gottstein and a multitude of original sound recordings collected on the internet, rearranged itself on every trip through an algorithm developed by Augst. In terms of content, the piece addressed the growing complexity of global financial systems, which even experts no longer fully understand.", "The constant recombination of sound fragments created multi-layered references that offered ironic commentary on the fragmented perception of modern financial systems while reflecting their contradictions and dynamics."], "fotos": "Gabriel Poblete · Helge Krückeberg · YRD.Works"}, {"year": "2021", "title": "Bread Dispenser", "jahr": "2021", "ort": "Frankfurt", "art": "Rauminstallation / Aktion", "desc": "Aktion, bei der Sauerteigbrot gebacken und über einen Brotautomaten unentgeltlich an das Publikum einer Galerie verteilt wurde", "text": ["Im Frühjahr 2021 präsentierten YRD.Works die Arbeit Bread Dispenser in der Frankfurter punktumweg Galerie. Über einen Zeitraum von zehn Tagen backte das Künstlerkollektiv täglich 50 Sauerteigbrote. Im Vorfeld des Projekts hatten sich die Künstler über Monate intensiv mit den Grundlagen dieses uralten Handwerks auseinandergesetzt und das Brotbacken erlernt, in Gesprächen mit Expert*innen und beim Probebacken nach deren Rezepten.", "Für die Aktion selbst unterteilten YRD.Works die Galerie mit Trockenbauwänden und schuf neben dem eigentlichen Ausstellungsraum einen zweiten, für das Publikum nicht einsehbaren Bereich. Dieser verborgene Rückraum war mit einem großen Backofen, einer Kühlkammer und anderen Geräten ausgestattet, hier wurden während der Öffnungszeiten der Galerie die Brotlaibe gebacken. Durch die räumliche Trennung konnten die Besucher*innen den Backprozess jedoch nur durch die Geräusche und den Duft aus der temporären Bäckerei erahnen.", "Anders als die Backstube wirkte der begehbare Ausstellungsraum leer und durch seine weißen Wände sowie das kühle Neonlicht beinahe steril. An zentraler Stelle befand sich ein in die Wand eingelassener Automat, dessen dunkler Ausgabeschacht direkt in die den Blicken verborgene Bäckerei führte.", "Mit einem Knopfdruck konnten die Besucher*innen einen Prozess auslösen, der dafür sorgte, dass jeweils ein frisch gebackenes Brot über den Schacht von der Backstube in die Galerie rutschte. Dieser Vorgang erinnerte an die Brotautomaten eines bekannten Discounters und stand in starkem Kontrast zu dem hochwertigen, in Handarbeit hergestellten Lebensmittel, das aus der Klappe entnommen werden konnte.", "Das Konzept der Ausstellung zielte darauf ab, das Projekt über den klassischen Kunstraum hinaus zu öffnen und einen karitativen, für jeden zugänglichen Raum zu schaffen: Durch ein großes Schaufenster zur Straße wurden auch Passant*innen und Anwohner*innen auf Bread Dispenser aufmerksam. Pro Person durfte täglich ein frisch gebackenes, oft noch ofenwarmes Brot kostenlos mitgenommen werden."], "gallery": [["Bilder/2021-bread-dispenser/01.webp", 1500, 1000], ["Bilder/2021-bread-dispenser/02.webp", 1504, 1000], ["Bilder/2021-bread-dispenser/03.webp", 1502, 1000], ["Bilder/2021-bread-dispenser/04.webp", 1502, 1000], ["Bilder/2021-bread-dispenser/05.webp", 666, 1000], ["Bilder/2021-bread-dispenser/06.webp", 665, 1000], ["Bilder/2021-bread-dispenser/07.webp", 665, 1000], ["Bilder/2021-bread-dispenser/08.webp", 665, 1000]], "text_en": ["In spring 2021, YRD.Works presented the work Bread Dispenser at punktumweg Galerie in Frankfurt. Over a period of ten days, the collective baked 50 sourdough loaves every day. In the months leading up to the project, the artists had studied the fundamentals of this ancient craft intensively and learned to bake bread, through conversations with experts and trial bakes using their recipes.", "For the action itself, YRD.Works divided the gallery with drywall partitions, creating a second area next to the actual exhibition space that the public could not see. This hidden back room was equipped with a large oven, a cold room and other equipment; here, the loaves were baked during the gallery's opening hours. Because of the spatial separation, however, visitors could only sense the baking process through the sounds and smells coming from the temporary bakery.", "Unlike the bakehouse, the walk-in exhibition space appeared empty and, with its white walls and cool neon light, almost sterile. At its centre was a dispenser set into the wall, whose dark chute led directly into the hidden bakery.", "At the push of a button, visitors could trigger a process that sent one freshly baked loaf sliding down the chute from the bakehouse into the gallery. The procedure recalled the bread machines of a well-known discount supermarket and stood in stark contrast to the high-quality, handmade food that could be taken from the hatch.", "The concept of the exhibition aimed to open the project beyond the conventional art space and to create a charitable space accessible to everyone: a large shop window facing the street drew the attention of passers-by and residents to Bread Dispenser. Each person was allowed to take one freshly baked, often still oven-warm loaf home for free each day."], "fotos": "Gabriel Poblete · YRD.Works"}, {"year": "2020", "title": "Logis", "jahr": "2020", "ort": "Dauernheim / Wetterau", "art": "Skulptur / Intervention / Aktion", "desc": "Mehrstöckige Skulptur, die gemeinsam mit Publikum in der Wetterau errichtet wird und in der anschließend mit 20 Personen übernachtet wird", "text": ["Im Sommer 2020 realisierten YRD.Works die selbstinitiierte Arbeit Logis in einem Naturschutzgebiet in der hessischen Wetterau. An einem Wochenende wurde eine 5 × 5 × 2,5 m große Skulptur aufgebaut, in der im Anschluss 20 Gäste übernachteten. Das weiße Holz-Bauwerk bestand aus insgesamt 20 gleichförmigen Schlafkabinen und erinnerte äußerlich durch seine fünf Stockwerke an die Miniatur eines Plattenbaus.", "Die auf einer Kuppe und inmitten von Streuobstwiesen positionierte Skulptur war schon aus der Ferne sichtbar. Die beidseitig geöffneten Seiten des Objekts ermöglichten den Besucher*innen einen uneingeschränkten Blick in das weitläufige Tal unterhalb des Hügels.", "Die Einzelteile des Baus wurden von YRD.Works im Vorfeld der Aktion aus recycelten Materialien vorgefertigt und anschließend in die Wetterau transportiert. So konnte die Schlafstätte innerhalb eines Tages gemeinsam von den Künstlern und ihren Gästen aufgebaut werden. Es war Teil des künstlerischen Konzepts, dass die Besucher*innen mit den nötigen Werkzeugen ausgestattet und aktiv in den Aufbau von Logis mit einbezogen wurden.", "Durch das kollektive Bauen und das anschließende gemeinsame Übernachten in dem Objekt hinterfragten YRD.Works bei Logis die Grenzen von Skulptur, Architektur und performativer Aktion."], "gallery": [["Bilder/2021-logis/01.webp", 1500, 1000], ["Bilder/2021-logis/02.webp", 1778, 1000], ["Bilder/2021-logis/03.webp", 667, 1000], ["Bilder/2021-logis/04.webp", 1499, 1000], ["Bilder/2021-logis/05.webp", 1778, 1000]], "text_en": ["In the summer of 2020, YRD.Works realised the self-initiated work Logis in a nature reserve in the Wetterau region of Hesse. Over one weekend, a 5 × 5 × 2.5 m sculpture was erected in which 20 guests then spent the night. The white timber structure consisted of 20 identical sleeping cabins and, with its five storeys, resembled a miniature prefabricated housing block.", "Positioned on a hilltop amid meadow orchards, the sculpture was visible from afar. Its open sides gave visitors an unobstructed view of the wide valley below the hill.", "YRD.Works prefabricated the individual parts from recycled materials before the action and then transported them to the Wetterau, so that the artists and their guests could assemble the sleeping place together within a single day. It was part of the artistic concept that visitors were equipped with the necessary tools and actively involved in building Logis.", "Through collective building and then spending the night together in the object, YRD.Works used Logis to question the boundaries between sculpture, architecture and performative action."], "fotos": "Dominik Dresel · YRD.Works"}, {"year": "2020", "title": "Canned (99/63)", "jahr": "2020", "ort": "Offenbach / Digital", "art": "Aktion / Livestream", "desc": "Performative Produktion von Konserven im Livestream", "text": ["Schon einige Monate vor der Corona-Pandemie hatten YRD.Works gemeinsam mit dem Künstlerhaus Mousonturm mit der Planung eines Projekts begonnen, bei dem regionale Lebensmittel in Dosen konserviert werden sollten. Durch den deutschlandweiten Lockdown im Frühjahr 2020 musste Canned (99/63) kurzerhand in den digitalen Raum verlegt werden, wodurch ein zehntägiges Streamingprojekt entstand. Die neuen, unvorhersehbaren Umstände zwangen YRD.Works zwar zu einigen technischen Änderungen am Konzept, jedoch thematisierte bereits die ursprüngliche Idee kulturelle Phänomene wie das Preppen von Lebensmitteln und Hamsterkäufe, die durch die Corona-Pandemie verstärkt in den gesellschaftlichen Fokus rückten.", "Canned (99/63) war eine temporäre Konservenfabrik, in der YRD.Works täglich bis zu 200 Konservendosen mit wechselnden Gerichten produzierten. Die Rezepte ergaben sich spontan aus dem unverkauften Gemüse und Obst eines Bio-Großmarkts, das täglich in größeren Mengen abgeholt werden konnte. Das Kochen und Konservieren der Gerichte wurde täglich auf einer eigens dafür eingerichteten Website live übertragen. Die Produktionsstätte war in drei nahezu identische Arbeitsbereiche unterteilt, die aus einer frontalen Kameraperspektive gefilmt und auf der Website zu einem digitalen Triptychon zusammengestellt wurden. Die drei getrennten Bereiche zeigten jeweils eine Etappe des Produktionsprozesses (Bestellungsannahme, Kochen der Speisen und Befüllen der Dosen) und verwiesen dabei gleichzeitig auf die noch ungewohnten Abstandsregelungen des ersten Lockdowns.", "Die Zuschauer*innen konnten per Telefon-Hotline in den Stream eingreifen und ihre Bestellungen live aufgeben, wodurch sie trotz der räumlichen Isolation selbst Teil des Projekts wurden. Die goldfarbenen Konservendosen wurden von YRD.Works fortlaufend nummeriert und als limitierte Edition an die Käufer*innen verschickt. Diese konnten entscheiden, ob sie die Dosen als Lebensmittel verbrauchen oder als Kunstobjekte der Aktion aufbewahren wollten."], "gallery": [["Bilder/2020-canned-99-63/01.webp", 1499, 1000], ["Bilder/2020-canned-99-63/02.webp", 667, 1000], ["Bilder/2020-canned-99-63/03.webp", 1499, 1000], ["Bilder/2020-canned-99-63/04.webp", 667, 1000], ["Bilder/2020-canned-99-63/05.webp", 1498, 1000], ["Bilder/2020-canned-99-63/06.webp", 667, 1000], ["Bilder/2020-canned-99-63/07.webp", 1498, 1000]], "text_en": ["A few months before the coronavirus pandemic, YRD.Works and Künstlerhaus Mousonturm had begun planning a project in which regional food was to be preserved in cans. Due to the nationwide lockdown in spring 2020, Canned (99/63) had to be moved into the digital realm at short notice, resulting in a ten-day streaming project. The new, unforeseeable circumstances forced YRD.Works to make some technical changes to the concept, but the original idea had already addressed cultural phenomena such as food prepping and panic buying, which the pandemic pushed further into public focus.", "Canned (99/63) was a temporary cannery in which YRD.Works produced up to 200 cans a day with changing dishes. The recipes arose spontaneously from the unsold vegetables and fruit of an organic wholesale market, which could be collected in larger quantities every day. The cooking and canning of the dishes was broadcast live every day on a dedicated website. The production site was divided into three almost identical work areas, filmed from a frontal camera perspective and combined on the website into a digital triptych. The three separate areas each showed one stage of the production process (taking orders, cooking the food and filling the cans) while also referencing the still unfamiliar distancing rules of the first lockdown.", "Viewers could intervene in the stream via a telephone hotline and place their orders live, becoming part of the project themselves despite spatial isolation. YRD.Works continuously numbered the gold-coloured cans and shipped them to buyers as a limited edition. The buyers could decide whether to consume the cans as food or keep them as art objects from the action."], "fotos": "Gabriel Poblete"}, {"year": "2020", "title": "Access", "jahr": "2020", "ort": "Frankfurt", "art": "Ausstellungsarchitektur", "desc": "Entwicklung und Umsetzung eines Ausstellungspavillons, in dem die Ausgrabung und Erforschung eines Bonebeds live mitverfolgt werden kann", "text": ["Im Rahmen einer Kooperation mit dem Senckenberg Naturmuseum Frankfurt und dem Frankfurter Kunstverein konzipierten und realisierten YRD.Works 2020 die architektonische Intervention Access. Die temporäre Installation bildete über ein Jahr lang die räumliche Basis für die partizipative Ausstellung Edmonds Urzeitreich über eine Dinosauriergrabung in Frankfurt. Von außen erinnerte Access an einen Pfahlbau, der sich durch seine Holzbauweise, aber vor allem durch seine Farbgebung stark von den umliegenden Bestandsgebäuden des Museums abhob.", "Im Inneren der 21 × 9 × 5 m großen Holzkonstruktion befand sich ein sogenanntes Bonebed, ein 20 m² großer Gesteinsblock voller fossiler Knochen. Das Bonebed war eigens für die Ausstellung aus Wyoming, USA, nach Frankfurt gebracht worden und wurde von einem Team aus Wissenschaftler*innen freigelegt und erforscht.", "YRD.Works gliederten die Installation in zwei Segmente: einen innen liegenden Laborbereich, in dem die Grabung stattfand, und einen Außenbereich, von dem aus die Besucher*innen die wissenschaftliche Arbeit beobachten konnten.", "Der weiße Innenraum diente als eine Art White Cube und verwandelte den Laborbereich in einen musealen Raum. Die Untersuchungen, die sonst hinter verschlossenen Türen stattfinden, konnte man hier verfolgen, und die Grabung und das Bonebed selbst wurden zum ästhetischen Objekt. Um den Laborbereich lag ein korallfarbener Außenbereich, den die Besucher*innen begehen konnten und der in starkem Kontrast zur neutralen Laborästhetik des Innenraums stand.", "Eine umlaufende, leicht ansteigende Rampe, die das Bonebed von allen vier Seiten umgab, ermöglichte dem Publikum die Sicht auf die Grabungsstätte aus unterschiedlichen Perspektiven.", "Tribünenartige Treppen an den Kopfseiten des Innen- und Außenraums boten den Besucher*innen Sitzplätze. Von hier aus konnten Interessierte den Forschenden Fragen stellen und die Grabung aus nächster Nähe verfolgen."], "gallery": [["Bilder/2020-access/01.webp", 1498, 1000], ["Bilder/2020-access/02.webp", 1414, 1000], ["Bilder/2020-access/03.webp", 1499, 1000], ["Bilder/2020-access/04.webp", 1499, 1000], ["Bilder/2020-access/05.webp", 668, 1000]], "text_en": ["As part of a collaboration with the Senckenberg Nature Museum Frankfurt and the Frankfurter Kunstverein, YRD.Works conceived and realised the architectural intervention Access in 2020. For over a year, the temporary installation formed the spatial basis for the participatory exhibition Edmonds Urzeitreich about a dinosaur excavation in Frankfurt. From the outside, Access resembled a pile dwelling that stood out strongly from the museum's surrounding buildings through its timber construction and above all its colour.", "Inside the 21 × 9 × 5 m timber structure was a so-called bonebed, a 20 m² block of rock full of fossil bones. The bonebed had been brought to Frankfurt from Wyoming, USA, especially for the exhibition and was uncovered and studied by a team of scientists.", "YRD.Works divided the installation into two segments: an inner laboratory area where the excavation took place, and an outer area from which visitors could observe the scientific work.", "The white interior served as a kind of white cube and turned the laboratory area into a museum space. Research that normally happens behind closed doors could be followed here, and the excavation and the bonebed itself became aesthetic objects. The laboratory area was surrounded by a coral-coloured outer area that visitors could walk through and that contrasted strongly with the neutral laboratory aesthetic of the interior.", "A gently rising ramp running around the bonebed on all four sides allowed the audience to view the excavation site from different perspectives.", "Grandstand-like steps at the ends of the interior and exterior spaces offered visitors places to sit. From here, those interested could ask the researchers questions and follow the excavation at close range."], "fotos": "Gabriel Poblete · Janosch Boerckel"}, {"year": "2019", "title": "Doubles", "jahr": "2019", "ort": "Nordhorn", "art": "Rauminstallation", "desc": "Einzelausstellung und begehbare Rauminstallation, die sich mit dem White Cube als Ausstellungsraum kritisch auseinandersetzt", "text": ["Im Zuge des Kunstpreises der Stadt Nordhorn 2018, mit dem YRD.Works ausgezeichnet wurde, präsentierte die Galerie Nordhorn vom 10. März bis zum 5. Mai 2019 eine ortsbezogene Rauminstallation des Künstlerkollektivs.", "Eigens für die Räumlichkeiten des Hauses entwickelten die Künstler eine räumliche Skulptur, die sich mit der vorgefundenen Architektur des klassischen White Cube und seiner Eigenheit auseinandersetzte. Ein modulartiges Stellwandsystem, das es ermöglicht, unterschiedliche räumliche Ausstellungssituationen in der Galerie herzustellen, bildete das Zentrum von Doubles. In einer exakten Eins-zu-Eins-Kopie des Originals duplizierten YRD.Works die vorhandenen Stellwände in Größe und Material und positionierten diese angrenzend an die ursprünglichen Wandmodule in der Ausstellungsfläche.", "Daraus entstand ein 300 m² großer, begehbarer Parcours aus originalen und nachgebauten Paneelen, die sich rein äußerlich nicht voneinander unterscheiden ließen. Nur Besucher*innen, die bereits mit der Ausstellungsarchitektur der Galerie Nordhorn vertraut waren, konnten möglicherweise ermitteln, welche Elemente von den Künstlern hinzugefügt wurden und welche bereits vorhanden waren.", "Walter Benjamins berühmter Begriff der \"Aura\", mit dem er vor mehr als achtzig Jahren originale Kunstwerke von ihren technischen Reproduktionen abgrenzte, steht in Doubles erneut zur Verhandlung. Umgibt die künstlerischen Nachbauten von YRD.Works eine andere Aura, eine andere Präsenz als die vorhandenen Ausstellungsdisplays? Und kann man überhaupt einen Unterschied zwischen Kunstwerk und Ausstellungsdesign erkennen? Die Installation rückt die tradierte Frage nach dem Original und seiner Kopie in den Fokus und lässt Besucher*innen selbst über die Wichtigkeit einer solchen Differenzierung entscheiden."], "gallery": [["Bilder/2019-doubles/01.webp", 1499, 1000], ["Bilder/2019-doubles/02.webp", 667, 1000], ["Bilder/2019-doubles/03.webp", 667, 1000], ["Bilder/2019-doubles/04.webp", 667, 1000], ["Bilder/2019-doubles/05.webp", 667, 1000], ["Bilder/2019-doubles/06.webp", 1499, 1000], ["Bilder/2019-doubles/07.webp", 1499, 1000], ["Bilder/2019-doubles/08.webp", 1499, 1000]], "text_en": ["Following the 2018 Art Prize of the City of Nordhorn, awarded to YRD.Works, Galerie Nordhorn presented a site-specific spatial installation by the collective from 10 March to 5 May 2019.", "Especially for the gallery's rooms, the artists developed a spatial sculpture that engaged with the existing architecture of the classic white cube and its particularities. At the centre of Doubles was a modular partition system that allowed different exhibition situations to be created in the gallery. In an exact one-to-one copy of the original, YRD.Works duplicated the existing partitions in size and material and positioned them adjacent to the original wall modules in the exhibition space.", "The result was a 300 m² walk-in course of original and replicated panels that could not be told apart by their appearance. Only visitors already familiar with Galerie Nordhorn's exhibition architecture might have been able to work out which elements were added by the artists and which were already there.", "Walter Benjamin's famous concept of the \"aura\", with which he distinguished original works of art from their technical reproductions more than eighty years ago, is up for negotiation once again in Doubles. Do YRD.Works' artistic replicas carry a different aura, a different presence than the existing exhibition displays? And can one tell the difference between artwork and exhibition design at all? The installation brings the traditional question of the original and its copy into focus and leaves it to visitors to decide how important such a distinction is."], "fotos": "Gabriel Poblete"}, {"year": "2019", "title": "Copy Service", "jahr": "2019", "ort": "Hannover", "art": "Skulptur", "desc": "Begehbare Skulptur, die eine riesige (vermeintliche) Gussform des Herrenhäuser Schlosses andeutet, das offensichtlich eine Reproduktion ist", "img": "Bilder/2019-copy-service/hero.webp", "text": ["Der Wiederaufbau des im Zweiten Weltkrieg zerstörten Schlosses Herrenhausen wurde in Hannover Anfang der 2000er Jahre kontrovers diskutiert. Während die Rekonstruktion das historische Stadtbild bereichern sollte, stieß sie auch auf Kritik, da viele Bürger*innen die Authentizität eines Neubaus infrage stellten.", "Im Mai 2019 realisierten YRD.Works die temporäre Installation Copy Service als Teil der KunstFestSpiele Herrenhausen im Ehrenhof des Schlosses Herrenhausen. Die 75 × 12 × 0,7 m große Skulptur lag dort wie ein Überbleibsel des Wiederaufbaus und vermittelte den Eindruck einer gigantischen Gussform. Die leuchtend blaue Konstruktion spiegelte die Merkmale der Fassade in invertierter Form wider: Fensteröffnungen wurden zu erhabenen Flächen und architektonische Ausstülpungen erschienen als Vertiefungen in der rund 900 m² großen Plattform. Die Negativform ließ die Schlossfassade wie eine Reproduktion erscheinen, als hätte das Objekt von YRD.Works tatsächlich als Gussform für den Nachbau gedient. So schob sich die Skulptur zwischen das historische Bauwerk und dessen Nachbildung und stellte eine vermeintliche technische Verbindung zwischen Original und Kopie dar.", "Die industrielle Anmutung der Gussform lenkte den Blick zudem auf die technische Möglichkeit, Bauwerke zu reproduzieren. Copy Service verwies damit auch auf andere Rekonstruktionsprojekte wie den Wiederaufbau der Frankfurter Altstadt oder des Berliner Stadtschlosses und stellte grundsätzlich die Frage nach der kulturellen Bedeutung solcher Nachbauten.", "Die Installation war frei begehbar und bot den Besucher*innen eine Plattform, die zugleich als Bühne genutzt werden konnte. Wie in früheren Arbeiten von YRD.Works verschwammen auch hier die Grenzen zwischen Betrachtung und Teilnahme, indem das Publikum selbst aktiv in die Skulptur einbezogen wurde. Gleichzeitig öffnete die Plattform symbolisch das Schloss, das sonst hauptsächlich privatwirtschaftlich als Event- und Tagungsstätte genutzt wird, und machte es so allen Bürger*innen Hannovers für einen kurzen Zeitraum zugänglich."], "gallery": [["Bilder/2019-copy-service/01.webp", 1781, 1000], ["Bilder/2019-copy-service/02.webp", 1498, 1000], ["Bilder/2019-copy-service/03.webp", 1499, 1000], ["Bilder/2019-copy-service/04.webp", 1499, 1000], ["Bilder/2019-copy-service/05.webp", 1499, 1000], ["Bilder/2019-copy-service/06.webp", 1499, 1000], ["Bilder/2019-copy-service/07.webp", 1499, 1000], ["Bilder/2019-copy-service/08.webp", 1781, 1000]], "text_en": ["The reconstruction of Herrenhausen Palace, destroyed in the Second World War, was the subject of controversial debate in Hanover in the early 2000s. While the reconstruction was meant to enrich the historic cityscape, it also met with criticism, as many citizens questioned the authenticity of a new building.", "In May 2019, YRD.Works realised the temporary installation Copy Service as part of KunstFestSpiele Herrenhausen in the cour d'honneur of Herrenhausen Palace. The 75 × 12 × 0.7 m sculpture lay there like a leftover from the reconstruction, giving the impression of a gigantic casting mould. The bright blue structure reflected the features of the façade in inverted form: window openings became raised surfaces and architectural projections appeared as recesses in the roughly 900 m² platform. The negative form made the palace façade look like a reproduction, as if YRD.Works' object had actually served as the mould for the rebuild. In this way, the sculpture inserted itself between the historic building and its replica and suggested a technical link between original and copy.", "The industrial appearance of the mould also drew attention to the technical possibility of reproducing buildings. Copy Service thus also pointed to other reconstruction projects such as the rebuilding of Frankfurt's old town or the Berlin Palace, and fundamentally raised the question of the cultural significance of such replicas.", "The installation was freely accessible and offered visitors a platform that could also be used as a stage. As in earlier works by YRD.Works, the boundaries between viewing and participation blurred, as the audience itself was actively drawn into the sculpture. At the same time, the platform symbolically opened up the palace, which is otherwise used mainly commercially as an event and conference venue, making it accessible to all of Hanover's citizens for a short time."], "kachel": "_kachel_copy-service.jpg", "fotos": "Gabriel Poblete · Gian Luca Kropp"}, {"year": "2018", "title": "White Out", "jahr": "2018", "ort": "Frankfurt", "art": "Rauminstallation / Intervention", "desc": "Rauminstallation und Intervention rund um die Glasfront eines Ausstellungsraums", "img": "Bilder/2018-white-out/hero.webp", "text": ["Die räumliche Installation White Out war im Rahmen des vierteiligen Kooperationsprojekts LoadNext zwischen dem Frankfurter Saasfee-Pavillon und der Kressmann-Halle Offenbach vom 15. November bis zum 6. Dezember 2018 im Saasfee-Pavillon in Frankfurt zu sehen. \"Whiteout\" bezeichnet ein meteorologisches Phänomen, das in Hochgebirgen und Polargebieten beobachtet werden kann. Treffen schneebedeckte Flächen auf ein durch Nebel gedämpftes Sonnenlicht, entsteht eine spezifische Helligkeit, die man \"Whiteout\" nennt. Durch den Einsatz künstlicher Techniken imitierten YRD.Works dieses spezifische Lichtverhältnis in einer raumgreifenden Installation in der Ausstellung.", "White Out begegnete den Besucher*innen als räumliche Intervention, die den gläsernen, lichtdurchfluteten Charakter des Saasfee-Pavillons stark veränderte. In einer 6 m hohen Außenverkleidung ummantelten YRD.Works die Fensterfront des Pavillons und errichteten einen externen Korridor, der die Ausstellungsfläche von ihrer äußeren Umgebung, den Parkanlagen, isolierte. Der 1 m breite, für die Besucher*innen verschlossene Zwischengang wurde künstlich beleuchtet und mit Nebel gefüllt, sodass die Sicht auf sein Inneres getrübt wurde.", "Ähnlich einem Diorama herrschte eine artifizielle Atmosphäre vor, in der jedoch nichts Konkretes sichtbar war. Exponierte bauliche Elemente innerhalb des vernebelten Gangs ließen lediglich an manchen Stellen eine räumliche Dimension erahnen. So entstand ein von seinen zeitlichen wie räumlichen Koordinaten unabhängiger Ort, der die Besucher*innen durch seine isolierte Leere herausforderte. Natürliche Einflüsse der äußeren Umgebung wie Jahreszeiten oder Wetterlagen wurden in White Out zugunsten einer statischen, geschlossenen Raumsituation bewusst negiert.", "An zwei Terminen während des Ausstellungszeitraums fanden Performances des Künstler*innen-Duos BBB_ und der Tänzerin Frances Chiaverini statt, die den räumlichen Charakter von White Out verstärkten."], "gallery": [["Bilder/2018-white-out/01.webp", 1400, 1000], ["Bilder/2018-white-out/02.webp", 714, 1000], ["Bilder/2018-white-out/03.webp", 714, 1000], ["Bilder/2018-white-out/04.webp", 714, 1000], ["Bilder/2018-white-out/05.webp", 714, 1000], ["Bilder/2018-white-out/06.webp", 714, 1000], ["Bilder/2018-white-out/07.webp", 714, 1000], ["Bilder/2018-white-out/08.webp", 667, 1000], ["Bilder/2018-white-out/09.webp", 714, 1000], ["Bilder/2018-white-out/10.webp", 714, 1000]], "text_en": ["The spatial installation White Out was on view at the Saasfee-Pavillon in Frankfurt from 15 November to 6 December 2018 as part of LoadNext, a four-part collaboration between the Saasfee-Pavillon and the Kressmann-Halle Offenbach. \"Whiteout\" describes a meteorological phenomenon that can be observed in high mountains and polar regions. When snow-covered surfaces meet sunlight muted by fog, a specific brightness arises that is called a whiteout. Using artificial techniques, YRD.Works imitated this particular light condition in an expansive installation in the exhibition.", "White Out confronted visitors as a spatial intervention that profoundly changed the glazed, light-flooded character of the Saasfee-Pavillon. With a 6 m high outer cladding, YRD.Works encased the pavilion's glass front and built an external corridor that isolated the exhibition space from its surroundings, the park. The 1 m wide passage, closed to visitors, was artificially lit and filled with fog, clouding the view of its interior.", "Much like a diorama, an artificial atmosphere prevailed in which, however, nothing concrete was visible. Exposed structural elements within the fogged corridor only hinted at a spatial dimension in places. The result was a place detached from its temporal and spatial coordinates that challenged visitors with its isolated emptiness. Natural influences from the surroundings such as seasons or weather were deliberately negated in White Out in favour of a static, closed spatial situation.", "On two dates during the exhibition, performances by the artist duo BBB_ and the dancer Frances Chiaverini took place, intensifying the spatial character of White Out."], "kachel": "_kachel_white-out.jpg", "fotos": "Camilo Brau"}, {"year": "2018", "title": "Oper Offenbach", "jahr": "2018", "ort": "Offenbach", "art": "Skulptur / Intervention / Aktion", "desc": "Entwicklung und inszenierte Umsetzung von vier Skulpturen, die als Bühnen genutzt werden und sich inhaltlich mit dem Thema Oper beschäftigen, über die Dauer von sechs Wochen", "text": ["Die Oper Offenbach fand als letzter Teil des kooperativen Projekts mit dem Künstlerhaus Mousonturm auf der Spitze der Hafeninsel in Offenbach statt, die an zwei Seiten von Binnengewässer umgeben ist. Das ungenutzte Terrain erlaubte es YRD.Works, in großen Dimensionen zu denken und ihr skulpturales Arbeiten in den städtischen Raum auszudehnen. So entstand dort die Oper Offenbach in einer mehrwöchigen, öffentlichen Inszenierung ihres Baus, der von Besucher*innen sowie Passant*innen in insgesamt vier Bauabschnitten beobachtet werden konnte.", "Die erste bauliche Intervention Prospekte setzte sich aus vier überdimensionierten Plakatwänden zusammen, die als Kollaboration mit dem Designerkollektiv Profi Aesthetics und dem Fotografen Simon Keckeisen entstanden. Die plakatierten Stellwände wurden auf der Hafeninsel positioniert und fungierten als Bühnenbild und Werbeträger zugleich, die selbst distanziertes Publikum an Land durch ihre exponierte Größe integrierten.", "Im nächsten Abschnitt des Baus wurde die Skulptur Graben realisiert, die den Orchestergraben eines Opernhauses neu interpretierte. Die räumliche Installation der Künstler, für die sie einen 15 m langen Graben aushoben, kehrte die ursprüngliche Funktion des Grabens um: Statt das Orchester zu verstecken, stellte sie die Musiker*innen explizit zur Schau. Aus einer erhöhten Aufsicht konnten Besucher*innen der Oper Offenbach während eines Spieltages ein Kammerorchester genauestens examinieren.", "In einem weiteren Bauschritt wurde ein weiterer traditioneller Teil eines Opernhauses, die Loge, ins szenische Zentrum gestellt. Das Separee, in dem der Wunsch nach individueller Exklusivität auf universelle Weise befriedigt wird, wurde von YRD.Works nachempfunden und konnte an drei Terminen gemietet werden. Die zehn Zwei-Personen-Logen wurden nachts von einer Harfenspielerin bespielt und erlaubten, was sonst beim Besuch einer Oper verpönt ist: das Schlafen.", "Im letzten Teil des Opernbaus, der Bühne, dekonstruierten YRD.Works erneut ein für die Oper typisches, architektonisches Element, die Drehbühne. Diese ermöglicht im herkömmlichen Gebrauch ein schnelles Wechseln des Bühnenbildes und eine effektvolle Inszenierung. Die skulpturale Interpretation der Drehbühne in der Oper Offenbach entledigte sich jedoch ihres technischen Kerns und gab Raum für das Publikum, welches aufgefordert wurde, das Innere der runden Skulptur zu erobern. Das Offenbacher Performance-Kollektiv Baby of Control setzte die Bühne, die sich nun außerhalb der Drehscheibe befand, in Szene.", "Im Prozessualen jedes einzelnen Bauabschnitts reflektieren YRD.Works das Theater und seine Inszenierung auf ungewohnte Weise und formulieren durch ihre Interpretationen den Versuch einer Neubewertung traditioneller Kunstrezeption."], "gallery": [["Bilder/2018-oper-offenbach/01.webp", 1779, 1000], ["Bilder/2018-oper-offenbach/02.webp", 1499, 1000], ["Bilder/2018-oper-offenbach/03.webp", 668, 1000], ["Bilder/2018-oper-offenbach/04.webp", 1499, 1000], ["Bilder/2018-oper-offenbach/05.webp", 1499, 1000], ["Bilder/2018-oper-offenbach/06.webp", 1506, 1000], ["Bilder/2018-oper-offenbach/07.webp", 1499, 1000], ["Bilder/2018-oper-offenbach/08.webp", 668, 1000], ["Bilder/2018-oper-offenbach/09.webp", 1499, 1000]], "text_en": ["Oper Offenbach (Offenbach Opera) took place as the final part of the collaborative project with Künstlerhaus Mousonturm on the tip of the harbour island in Offenbach, which is surrounded by inland waters on two sides. The unused terrain allowed YRD.Works to think on a large scale and extend their sculptural practice into urban space. Oper Offenbach was created there in a public staging of its construction over several weeks, which visitors and passers-by could follow in a total of four building phases.", "The first built intervention, Prospekte (Backdrops), consisted of four oversized billboards created in collaboration with the design collective Profi Aesthetics and the photographer Simon Keckeisen. The posted walls were placed on the harbour island and acted as stage set and advertising medium at once, drawing in even a distant audience on land through their exposed size.", "In the next phase of construction, the sculpture Graben (Pit) was realised, a reinterpretation of an opera house's orchestra pit. The artists' spatial installation, for which they dug a 15 m long trench, reversed the original function of the pit: instead of hiding the orchestra, it explicitly put the musicians on display. From an elevated viewpoint, visitors to Oper Offenbach could closely examine a chamber orchestra during a performance day.", "In a further step, another traditional part of an opera house, the box, was placed at the scenic centre. YRD.Works recreated the private box, in which the desire for individual exclusivity is satisfied in a universal way, and it could be rented on three dates. The ten two-person boxes were played to at night by a harpist and allowed what is otherwise frowned upon at the opera: sleeping.", "In the last part of the opera construction, the stage, YRD.Works once again deconstructed an architectural element typical of opera, the revolving stage. In conventional use, it allows quick scene changes and effective staging. The sculptural interpretation of the revolving stage in Oper Offenbach, however, shed its technical core and made room for the audience, who were invited to conquer the inside of the round sculpture. The Offenbach performance collective Baby of Control performed on the stage, which now lay outside the turntable.", "In the process of each individual building phase, YRD.Works reflect on theatre and its staging in an unusual way and, through their interpretations, attempt a reassessment of the traditional reception of art."], "fotos": "Gabriel Poblete · Daniel Herzog · YRD.Works"}, {"year": "2018", "title": "Not Not Pizza", "jahr": "2018", "ort": "Offenbach", "art": "Intervention / Performance", "desc": "Temporärer Pizza-Lieferdienst, der den Kunden Pizzen als Kunstwerke (Edition) mit einem Motorroller nach Hause liefert", "text": ["In der performativen Installation Not Not Pizza, die 2018 als Kollaboration zwischen YRD.Works und dem Künstler und Grafiker Eike König entstand, verwandelte sich die Kressmann-Halle in Offenbach im Zeitraum von zwei Wochen in einen temporären Pizzalieferdienst. Dort stellten die Künstler Pizzen in drei unterschiedlichen Ausführungen her und lieferten diese in speziellen Verpackungen aus, die von König handbedruckt und nummeriert als fortlaufende Edition gestaltet wurden. An den 14 Tagen konnte man unter einer speziell dafür eingerichteten Hotline die Künstler in ihrer Pop-up-Pizzeria erreichen und sich Bestellungen nach Hause liefern lassen.", "Die rund 500 Pizzen, die in dieser Zeit von Hand produziert wurden, stellten die Künstler persönlich mit Motorrollern zu und transportierten so ihre Aktion in die gesamte Stadt. Dadurch entstand eine ungewohnte Form der Kunstrezeption. Die Besucher*innen bzw. Kund*innen mussten nicht vor Ort sein, sie nahmen auch von ihren Privaträumen aus an Not Not Pizza teil. An zwei Terminen öffnete sich die Produktionsstätte auch in der Kressmann-Halle für die Öffentlichkeit, wodurch es den Besucher*innen möglich wurde, die Künstler bei ihrer Performance live zu beobachten.", "Das Interieur der Pizzeria wurde so originalgetreu nachempfunden, dass ein Unterschied zwischen alltäglichem Lieferservice und inszenierter Kunstperformance kaum erkennbar wurde. Sind es limitierte, von Hand gefertigte Editionen essbarer Kunstobjekte oder bloß gewöhnliches Fast Food, das von den Künstlern verbreitet wurde?", "Not Not Pizza spielt mit klassischen Strategien von Ausstellungen und den Entscheidungen, die hinter der Präsentation von Kunst stehen. Wer bestimmt den Inhalt von Ausstellungen, und kann sich dieser Inhalt gegebenenfalls auch von seinem Standort emanzipieren?"], "gallery": [["Bilder/2018-not-not-pizza/01.webp", 1499, 1000], ["Bilder/2018-not-not-pizza/02.webp", 1500, 1000], ["Bilder/2018-not-not-pizza/03.webp", 1500, 1000], ["Bilder/2018-not-not-pizza/04.webp", 667, 1000], ["Bilder/2018-not-not-pizza/05.webp", 667, 1000], ["Bilder/2018-not-not-pizza/06.webp", 1499, 1000], ["Bilder/2018-not-not-pizza/07.webp", 1499, 1000], ["Bilder/2018-not-not-pizza/08.webp", 668, 1000], ["Bilder/2018-not-not-pizza/09.webp", 1499, 1000], ["Bilder/2018-not-not-pizza/10.webp", 1499, 1000]], "text_en": ["In the performative installation Not Not Pizza, created in 2018 as a collaboration between YRD.Works and the artist and graphic designer Eike König, the Kressmann-Halle in Offenbach was transformed into a temporary pizza delivery service for two weeks. There, the artists made pizzas in three different versions and delivered them in special boxes, hand-printed by König and numbered as an ongoing edition. For 14 days, a dedicated hotline connected callers with the artists in their pop-up pizzeria to have orders delivered to their homes.", "The artists personally delivered the roughly 500 pizzas, produced by hand during this time, on scooters, carrying their action across the entire city. This created an unusual form of art reception. Visitors or customers did not have to be on site; they could also take part in Not Not Pizza from their own homes. On two dates, the production site in the Kressmann-Halle was also opened to the public, allowing visitors to watch the artists' performance live.", "The interior of the pizzeria was recreated so faithfully that the difference between an everyday delivery service and a staged art performance was barely recognisable. Were these limited, handmade editions of edible art objects, or just ordinary fast food distributed by the artists?", "Not Not Pizza plays with classic exhibition strategies and the decisions behind the presentation of art. Who determines the content of exhibitions, and can that content, if need be, emancipate itself from its location?"], "fotos": "Gabriel Poblete · YRD.Works"}, {"year": "2018", "title": "Insight Out", "jahr": "2018", "ort": "Frankfurt", "art": "Rauminstallation", "desc": "Temporärer Club aus transluzenten Gaze-Rahmen im Saal eines Theaters", "text": ["Insight Out war am 6. und 12. Januar 2018 als dritte Episode der Kooperation im Theatersaal des Mousonturms zu sehen. Die Installation stand als quadratischer Raum im Raum in der Mitte der Blackbox und teilte den Saal in zwei Bereiche. Innen lag ein begehbarer, mehrwandiger Hybrid aus Club und Skulptur, in dem zwei Nächte lang getanzt wurde. Außen blieb ein Umraum, von dem aus man die Konstruktion und ihr Inneres betrachten konnte. In der Mitte des Kubus lagen in einem eigenen, abgetrennten Raum das DJ-Pult und eine Bar, die man nur über die Tanzfläche erreichte.", "Die Wände waren mit Gaze bespannt. Von außen machten unterschiedliche Lichtquellen die einzelnen Schichten sichtbar, von innen war durch die Lichtsetzung nichts dahinter zu erkennen. So teilte die Installation die Blackbox räumlich und sozial. Wer draußen stand, konnte das Geschehen hinter den durchscheinenden Wänden unbemerkt beobachten. Wer drinnen tanzte, wurde selbst beobachtet.", "Auch Technik und Konstruktion legte die Installation offen. Kabel, Lichtquellen und Trägerelemente aus dem Bestand des Theaters hingen sichtbar an den Außenwänden. Die Theatertechnik, die sonst im Hintergrund bleibt, wurde so Teil der Arbeit und verwies auf den Ort, an dem sie stand. Der Innenraum blieb frei von Technik. Dort herrschte eine leere, an einen White Cube erinnernde Situation, die erst durch die Besucher*innen gefüllt wurde.", "Wer die Installation betrat, geriet in diese Umkehrung von innen und außen, auf die schon der Titel anspielt. Musik kam an beiden Abenden von den Kollektiven HardWorkSoftDrink und Hotel International."], "gallery": [["Bilder/2018-insight-out/01.webp", 1499, 1000], ["Bilder/2018-insight-out/02.webp", 1499, 1000], ["Bilder/2018-insight-out/03.webp", 1499, 1000], ["Bilder/2018-insight-out/04.webp", 1499, 1000], ["Bilder/2018-insight-out/05.webp", 1499, 1000], ["Bilder/2018-insight-out/06.webp", 1500, 1000], ["Bilder/2018-insight-out/07.webp", 1499, 1000], ["Bilder/2018-insight-out/08.webp", 1498, 1000], ["Bilder/2018-insight-out/09.webp", 1499, 1000]], "text_en": ["Insight Out was on view on 6 and 12 January 2018 as the third episode of the collaboration in the theatre hall of the Mousonturm. The installation stood as a square room within a room in the middle of the black box and divided the hall into two areas. Inside was a walk-in, multi-walled hybrid of club and sculpture where people danced for two nights. Outside remained a surrounding space from which the construction and its interior could be viewed. At the centre of the cube, in a separate room of its own, were the DJ booth and a bar that could only be reached across the dance floor.", "The walls were covered with gauze. From outside, different light sources made the individual layers visible; from inside, the lighting made it impossible to see what lay beyond. The installation thus divided the black box both spatially and socially. Those standing outside could watch what happened behind the translucent walls unnoticed. Those dancing inside were being watched themselves.", "The installation also exposed its technology and construction. Cables, light sources and support elements from the theatre's own stock hung visibly on the outer walls. The theatre technology that usually stays in the background became part of the work and pointed to the place where it stood. The interior remained free of technology. It was an empty, white-cube-like situation that was only filled by the visitors.", "Anyone entering the installation found themselves in this reversal of inside and outside, which the title already alludes to. The music on both evenings came from the collectives HardWorkSoftDrink and Hotel International."], "fotos": "Gabriel Poblete"}, {"year": "2017", "title": "1. Offenbacher Seefestspiele", "jahr": "2017", "ort": "Offenbach", "art": "Skulptur / Intervention / Performance", "desc": "Bau eines künstlichen Sees mithilfe von Betonwänden, auf und in dem performative Aktionen vor Publikum stattfinden", "img": "Bilder/2017-offenbacher-seefestspiele/hero.webp", "text": ["Als zweiten Teil der Zusammenarbeit zwischen YRD.Works und dem Künstlerhaus Mousonturm fanden die 1. Offenbacher Seefestspiele im Sommer 2017 im Außenbereich der Kressmann-Halle in Offenbach statt. Den Impuls zu dieser Arbeit setzte das urbane Umfeld der Künstler, welches zu großen Teilen durch leerstehende Brachflächen gekennzeichnet ist, die unterdessen in einen ungleichen Dialog mit den einheitlichen Neubauten im Hafenareal getreten sind. Gemeinsamkeiten mit konventionellen Seefestspielen wie in Bregenz oder Berlin sind nur schwer zu finden, doch genau das reizte das Künstlerkollektiv. Wie könnten Seefestspiele in einer Stadt wie Offenbach aussehen?", "Vieles steht im Wohn- und Lebensort der Künstler im Umbruch, woraus sich wiederum neue Brüche generieren. Ausgangspunkt für die raumgreifende Skulptur im Außenbereich der Kressmann-Halle war ein solcher Bruch: ein baulicher Fehler, der nach dem Bau einer neuen, angrenzenden Straße entstanden war. Seitdem staute sich auf dem Gelände der Kressmann-Halle bei starkem Regenfall eine stehende Wasserlache, die den Künstlern ins Auge fiel. YRD.Works machten sich diesen Defekt zunutze und errichteten an jener Stelle ein 600 m² großes betoniertes Bassin, das sie mit 180.000 Litern Wasser fluteten.", "Die künstlich entstandene Wasseroberfläche diente den 1. Offenbacher Seefestspielen als Bühne und begehbare Skulptur zugleich, die von contact Gonzo und Les Trucs mit performativen Aktionen während der Austragung der Seefestspiele inszeniert wurde. Der ironische Umgang mit tradierten Kulturstätten und die Entkontextualisierung ihres bedeutungsschweren Ambientes steht, ebenso wie die Neuverhandlung der kulturellen Bedeutung jener Standorte, im Zentrum der Aktion.", "Die Installation des Künstlerkollektivs gibt eine experimentelle Antwort auf das Format des Seefestspiels, dessen traditionelle Strategien und Erwartungen infiltriert und schlussendlich gebrochen werden."], "gallery": [["Bilder/2017-offenbacher-seefestspiele/01.webp", 667, 1000], ["Bilder/2017-offenbacher-seefestspiele/02.webp", 667, 1000], ["Bilder/2017-offenbacher-seefestspiele/03.webp", 1500, 1000], ["Bilder/2017-offenbacher-seefestspiele/04.webp", 1499, 1000], ["Bilder/2017-offenbacher-seefestspiele/05.webp", 1502, 1000], ["Bilder/2017-offenbacher-seefestspiele/06.webp", 1502, 1000], ["Bilder/2017-offenbacher-seefestspiele/07.webp", 1502, 1000], ["Bilder/2017-offenbacher-seefestspiele/08.webp", 1502, 1000], ["Bilder/2017-offenbacher-seefestspiele/09.webp", 1503, 1000]], "text_en": ["As the second part of the collaboration between YRD.Works and Künstlerhaus Mousonturm, the 1. Offenbacher Seefestspiele (1st Offenbach Lake Festival) took place in summer 2017 in the outdoor area of the Kressmann-Halle in Offenbach. The impulse for this work came from the artists' urban surroundings, largely characterised by vacant wasteland that has since entered into an unequal dialogue with the uniform new buildings of the harbour area. Similarities with conventional lake festivals such as those in Bregenz or Berlin are hard to find, and that is exactly what appealed to the collective. What might a lake festival look like in a city like Offenbach?", "Much is in flux in the place where the artists live and work, and this in turn produces new ruptures. The starting point for the expansive sculpture in the outdoor area of the Kressmann-Halle was one such rupture: a construction fault that arose after a new adjacent road was built. Since then, during heavy rain, a pool of standing water collected on the grounds of the Kressmann-Halle, which caught the artists' eye. YRD.Works made use of this defect and built a 600 m² concrete basin on the spot, which they flooded with 180,000 litres of water.", "The artificial water surface served the 1. Offenbacher Seefestspiele as both stage and walk-in sculpture, staged with performative actions by contact Gonzo and Les Trucs during the festival. The ironic treatment of traditional cultural venues and the decontextualisation of their weighty ambience are at the centre of the action, as is the renegotiation of the cultural significance of such sites.", "The collective's installation offers an experimental response to the format of the lake festival, whose traditional strategies and expectations are infiltrated and ultimately broken."], "kachel": "04_4.jpg", "fotos": "Gabriel Poblete · YRD.Works"}, {"year": "2017", "title": "Messerschmiede", "jahr": "2017", "ort": "Frankfurt", "art": "Rauminstallation / Intervention / Performance", "desc": "Herstellung von 100 Messern in einer dafür gebauten öffentlichen Werkstatt in einem Theater", "text": ["Den Auftakt der zweijährigen Kooperation zwischen YRD.Works und dem Künstlerhaus Mousonturm bildete die Installation Messerschmiede, die 2017 im Innen- und Außenbereich des Mousonturms zu sehen war. Als eine Art Parasit, der sich in die Architektur des Theaters einnistete, okkupierte das Künstlerkollektiv mit einer 12 m langen Box, in der sich die Messerschmiede befand, das Restaurant und einen Teil des Außengeländes. Dort produzierten sie innerhalb von 14 Tagen eine Edition von 100 handgefertigten Messern, die mit einer gestanzten Ziffern- und Buchstabenkombination nummeriert wurden.", "Die rechteckige Skulptur bestand aus vier Bereichen, welche verschiedene Schritte der Messerproduktion markierten. Im Außenbereich befand sich die erste Zone, in der Besucher*innen die Künstler beim Bearbeiten der Messerrohlinge durch verglaste Fensteröffnungen beobachten konnten. Der daran angrenzende Raum formte einen fließenden Übergang zum Inneren des Restaurants, der zur Weiterverarbeitung der Metalle diente und ebenfalls durch Glasscheiben betrachtet werden konnte. Im nächsten, darauffolgenden Abschnitt wurden die geschliffenen Messer mit Holzgriffen bestückt und im letzten Raum als finale Produkte verkaufsbereit präsentiert.", "Die kleine temporäre Fabrik bezog Besucher*innen des Mousonturms unweigerlich in die Messerproduktion mit ein und ließ sie Teil der zweiwöchigen Performance werden. Die Künstler übernahmen in dieser Zeit die Rolle des Handwerkers und inszenierten ihre kurzlebige Produktionsstätte in einer ungeschönten Version, die den Blick auf technische und produktionsbedingte Einzelheiten freigab. Das Zeigen der schrittweisen Entstehung eines Messers rückte, neben Fragen zur Produktion von Gegenständen, auch den ambivalenten Charakter des Messers als Werkzeug und Waffe zugleich ins Zentrum.", "Entstanden in der Messerschmiede also handgefertigte Alltagsgegenstände oder limitierte Kunstwerke? Und hatte man es hier mit einer künstlerischen Performance oder einem kommerziellen Pop-up-Shop zu tun? YRD.Works hinterfragen in ihrer performativen Intervention nicht nur gängige Produktions- und Bewertungssysteme von Kunst, sondern auch deren ökonomische und soziale Regelungen."], "gallery": [["Bilder/2017-messerschmiede/01.webp", 1502, 1000], ["Bilder/2017-messerschmiede/02.webp", 666, 1000], ["Bilder/2017-messerschmiede/03.webp", 666, 1000], ["Bilder/2017-messerschmiede/04.webp", 666, 1000], ["Bilder/2017-messerschmiede/05.webp", 1502, 1000], ["Bilder/2017-messerschmiede/06.webp", 666, 1000], ["Bilder/2017-messerschmiede/07.webp", 666, 1000], ["Bilder/2017-messerschmiede/08.webp", 666, 1000], ["Bilder/2017-messerschmiede/09.webp", 666, 1000], ["Bilder/2017-messerschmiede/10.webp", 1895, 1000]], "text_en": ["The two-year collaboration between YRD.Works and Künstlerhaus Mousonturm opened with the installation Messerschmiede (Knife Forge), on view in 2017 inside and outside the Mousonturm. Like a parasite nesting in the theatre's architecture, the collective occupied the restaurant and part of the outdoor grounds with a 12 m long box housing the forge. There, within 14 days, they produced an edition of 100 handmade knives, each numbered with a stamped combination of digits and letters.", "The rectangular sculpture consisted of four areas marking different steps of knife production. The first zone was outdoors, where visitors could watch the artists working the knife blanks through glazed openings. The adjoining room formed a fluid transition into the restaurant; it served for further processing of the metal and could also be viewed through glass. In the next section, the ground knives were fitted with wooden handles, and in the last room they were presented as finished products ready for sale.", "The small temporary factory inevitably drew visitors to the Mousonturm into knife production and made them part of the two-week performance. During this time, the artists took on the role of craftsmen and staged their short-lived production site in an unvarnished version that revealed technical and production-related details. Showing the step-by-step making of a knife brought into focus not only questions about the production of objects but also the ambivalent character of the knife as both tool and weapon.", "So were handmade everyday objects or limited artworks being made in the Messerschmiede? And was this an artistic performance or a commercial pop-up shop? In their performative intervention, YRD.Works question not only common systems of producing and valuing art but also their economic and social rules."], "fotos": "Gabriel Poblete · YRD.Works"}, {"year": "2017", "title": "Eins zu Eins", "jahr": "2017", "ort": "Frankfurt", "art": "Rauminstallation / Skulptur", "desc": "Raumgreifende Skulptur im Frankfurter Kunstverein, der den Ausstellungsraum in abstrakter und zerlegter Form darstellt und ihn begehbar macht", "text": ["Eins zu Eins entstand im Rahmen der Gruppenausstellung Things I think I want, die im Frühjahr 2017 im Frankfurter Kunstverein zu sehen war. Die zentrale Thematik der Arbeit entwickelte sich aus einem raumbezogenen Diskurs, den das Künstlerkollektiv in einer intensiven Auseinandersetzung mit der örtlichen Ausstellungsarchitektur erfuhr. Insbesondere das Zurücktreten der technischen und baulichen Fertigung eines Ausstellungsraums zugunsten einer störungsfreien Rezeption von Kunst beschäftigte die Künstler dabei. Das Vermeiden der Interaktion von vorhandener Architektur und Kunstwerk in zeitgenössischen Ausstellungen regte YRD.Works dazu an, die vorgefundene Materialität des Frankfurter Kunstvereins einer Dekonstruktion zu unterziehen.", "Daraus entstand Eins zu Eins, eine raumgreifende Skulptur, die aus der Zerlegung einer maßstabsgetreuen Reproduktion des größten Raums im Obergeschoss des Kunstvereins bestand. Die Künstler teilten den Raum anhand der technischen Abfolge von Wänden und Deckenelementen auf und ordneten ihn neu zusammengesetzt am Boden des Realraums an. Als eigentümliche Dopplung der Ausstellungsarchitektur, die von ihrer ursprünglichen Nutzung befreit wurde, verhandelte sich Eins zu Eins in einem neuen Kontext. Die dekonstruierte Replik des Raums existierte nun als autonome, raumfüllende Skulptur, die begehbar war.", "Die weiße Oberfläche des Objekts nutzte sich über die Dauer der Ausstellung durch die Interaktion der Besucher*innen immer weiter ab und konservierte gleichzeitig die unterschiedlichen Spuren des Gebrauchs. Durch das Involvieren der Betrachter*innen formte sich neben der Infragestellung einer Hierarchie des Raums auch eine Kritik an der sakralen Unantastbarkeit des Kunstwerks als solchen. Was passiert durch das Aushebeln solcher tradierten Rangordnungen? Und kann so etwas wie ein demokratischer Raum für Kunst überhaupt existieren?", "Als räumlicher Versuch einer Neuskalierung konventioneller Strukturen von Ausstellungen stellt Eins zu Eins das Verhältnis von Besucher*innen und Kunst in einen neuen Dialog."], "gallery": [["Bilder/2017-eins-zu-eins/01.webp", 1499, 1000], ["Bilder/2017-eins-zu-eins/02.webp", 1500, 1000], ["Bilder/2017-eins-zu-eins/03.webp", 1500, 1000], ["Bilder/2017-eins-zu-eins/04.webp", 1500, 1000], ["Bilder/2017-eins-zu-eins/05.webp", 1500, 1000], ["Bilder/2017-eins-zu-eins/06.webp", 1500, 1000], ["Bilder/2017-eins-zu-eins/07.webp", 1499, 1000]], "text_en": ["Eins zu Eins (One to One) was created for the group exhibition Things I think I want, shown at the Frankfurter Kunstverein in spring 2017. The central theme of the work developed from a site-related discourse the collective engaged in through an intensive study of the venue's exhibition architecture. The artists were particularly concerned with how the technical and structural making of an exhibition space recedes in favour of an undisturbed reception of art. The avoidance of interaction between existing architecture and artwork in contemporary exhibitions prompted YRD.Works to subject the Frankfurter Kunstverein's materiality to a deconstruction.", "The result was Eins zu Eins, an expansive sculpture consisting of the dismantled, true-to-scale reproduction of the largest room on the Kunstverein's upper floor. The artists divided the room according to the technical sequence of walls and ceiling elements and rearranged it, reassembled, on the floor of the actual room. As a peculiar doubling of the exhibition architecture, freed from its original use, Eins zu Eins was negotiated in a new context. The deconstructed replica of the room existed as an autonomous, room-filling sculpture that visitors could walk on.", "Over the course of the exhibition, the object's white surface wore down more and more through visitors' interaction, while at the same time preserving the various traces of use. By involving viewers, the work questioned the hierarchy of space and also formed a critique of the sacred untouchability of the artwork as such. What happens when such traditional hierarchies are undermined? And can something like a democratic space for art exist at all?", "As a spatial attempt to rescale the conventional structures of exhibitions, Eins zu Eins places the relationship between visitors and art in a new dialogue."], "fotos": "Gabriel Poblete"}, {"year": "2017", "title": "Busy Sculpture", "jahr": "2017", "ort": "Offenbach", "art": "Skulptur", "desc": "Entwicklung eines Wasserrads, das fähig ist, Strom zu erzeugen und Kryptowährungen zu schürfen", "text": ["Busy Sculpture ist ein Wasserrad, das fähig ist, Kryptowährungen zu generieren. Das Rad kann die kinetische Energie eines Flusses in Strom verwandeln und damit einen Computer (\"Miner\") betreiben, der Transaktionen auf einer Blockchain verifiziert. Diese Verifikationen werden in Form der jeweiligen Kryptowährung vergütet, was es der Skulptur ermöglicht, ein eigenes Einkommen zu erwirtschaften.", "Busy Sculpture kann über einen Surf-Stick mit einer Blockchain verbunden werden und so an den entlegensten Orten an einem globalen Finanz-Netzwerk partizipieren. Die Skulptur steht als Blueprint u. a. für die Möglichkeit einer neuen, dezentralen Energiegewinnung, da sie nicht ortsgebunden ist und der gewonnene Strom ohne Verluste durch lange Übertragungsstrecken in Kryptogeld verwandelt werden kann.", "Gleichzeitig ist Busy Sculpture ein wirtschaftliches Perpetuum mobile, da die gewonnenen Coins in dem von YRD.Works gebauten Modell gerade ausreichen, um die Kosten des Surf-Sticks zu decken und die Skulptur somit in gewisser Weise zum Selbstzweck Geld generiert."], "gallery": [["Bilder/2017-busy-sculpture/01.webp", 1500, 1000], ["Bilder/2017-busy-sculpture/02.webp", 1452, 1000], ["Bilder/2017-busy-sculpture/03.webp", 1477, 1000], ["Bilder/2017-busy-sculpture/04.webp", 1468, 1000], ["Bilder/2017-busy-sculpture/05.webp", 1510, 1000], ["Bilder/2017-busy-sculpture/06.webp", 1410, 1000], ["Bilder/2017-busy-sculpture/07.webp", 712, 1000]], "text_en": ["Busy Sculpture is a water wheel capable of generating cryptocurrency. The wheel can convert the kinetic energy of a river into electricity and use it to run a computer (a \"miner\") that verifies transactions on a blockchain. These verifications are rewarded in the respective cryptocurrency, allowing the sculpture to earn its own income.", "Busy Sculpture can be connected to a blockchain via a mobile internet stick and so participate in a global financial network from the most remote places. Among other things, the sculpture serves as a blueprint for the possibility of a new, decentralised form of energy generation, since it is not tied to a location and the electricity it produces can be converted into crypto money without losses from long transmission lines.", "At the same time, Busy Sculpture is an economic perpetual motion machine, as the coins earned in the model built by YRD.Works are just enough to cover the cost of the internet stick, so the sculpture, in a sense, generates money for its own sake."], "fotos": "YRD.Works"}, {"year": "2016", "title": "Sirenen", "jahr": "2016", "ort": "Offenbach", "art": "Lichtinstallation", "desc": "Lichtinstallation auf der Hafeninsel in Offenbach", "text": ["Die Lichtinstallation Sirenen entwickelten YRD.Works anlässlich der Luminale 2016 für die Offenbacher Hafeninsel, eine Landzunge, an der sich der Main in zwei Arme teilt, von denen einer ins Hafenbecken führt. In gewisser Weise war sie eine Folgearbeit von Makoko, der schwimmenden Lichtinstallation, die das Kollektiv zwei Jahre zuvor zur Luminale im Offenbacher Hafenbecken gezeigt hatte.", "Der Titel spielt mit der doppelten Bedeutung des Wortes: Im Mythos sitzen die Sirenen am Wasser und locken die vorbeifahrenden Seeleute, als technisches Signal warnt die Sirene. Die Tafeln an der Spitze der Landzunge taten beides zugleich, ähnlich wie ein Leuchtturm, der den Blick anzieht und dabei Orientierung gibt. YRD.Works interessierte dabei vor allem Licht als Signal und als Form der Kommunikation.", "Die Installation bestand aus fünf beidseitig leuchtenden, 3 × 5 m großen Tafeln, die an der äußersten Spitze der Landzunge aufgereiht waren und auf beide Mainarme strahlten. Aufgehängt an Metallstangen, die im Boden einbetoniert waren, bewegten sie sich dank ihrer großen Oberfläche frei im Wind. Über einen DMX-Controller liefen programmierte Lichtabläufe, mit denen die Tafeln Signale an vorbeifahrende Schiffe und an die Betrachtenden am Ufer sendeten."], "gallery": [["Bilder/2016-sirenen/01.webp", 1788, 1000], ["Bilder/2016-sirenen/02.webp", 1499, 1000], ["Bilder/2016-sirenen/03.webp", 1500, 1000], ["Bilder/2016-sirenen/04.webp", 1499, 1000]], "text_en": ["YRD.Works developed the light installation Sirenen (Sirens) on the occasion of Luminale 2016 for Offenbach's Hafeninsel, a spit of land where the Main divides into two arms, one of which leads into the harbour basin. In a certain sense, it was a follow-up to Makoko, the floating light installation the collective had shown in the Offenbach harbour basin at Luminale two years earlier.", "The title plays on the double meaning of the word: in myth, the sirens sit by the water and lure passing sailors; as a technical signal, the siren warns. The panels at the tip of the spit did both at once, much like a lighthouse that draws the eye while giving orientation. What interested YRD.Works above all was light as a signal and as a form of communication.", "The installation consisted of five double-sided light panels measuring 3 × 5 m, lined up at the very tip of the spit and shining onto both arms of the Main. Suspended from metal poles set in concrete in the ground, they moved freely in the wind thanks to their large surface. Programmed light sequences ran via a DMX controller, with which the panels sent signals to passing ships and to viewers on the bank."], "fotos": "Dominik Dresel"}, {"year": "2016", "title": "Scale Scale Scale", "jahr": "2016", "ort": "Offenbach", "art": "Rauminstallation", "desc": "Begehbare Rauminstallation in eigenem Projektraum", "text": ["Scale Scale Scale eröffnete 2016 als raumgreifende Installation, die in Kooperation mit dem Künstlerkollektiv D665 realisiert wurde, die zweite Ausstellung in der Kressmann-Halle in Offenbach. Ausgangspunkt der Arbeit bildete die gemeinsame theoretische Auseinandersetzung mit der Funktion und Ästhetik der Ausstellungsräume, die einige Monate zuvor von YRD.Works errichtet worden waren. Wie funktionieren Räume, die für Kunst oder Theater geschaffen werden? Nach welchen Kriterien werden diese bemessen? Und welche Auswirkung haben räumliche Gegebenheiten auf die Betrachtenden?", "In Scale Scale Scale entwickelten YRD.Works eine Intervention im Raum, die buchstäblich den Maßstab, die Skalierung (engl. Scale) der Kressmann-Halle in den Fokus nahm. Dafür unterteilten sie die 160 m² große Halle, die von ihnen einige Monate zuvor als Ausstellungsraum errichtet worden war, durch temporäre Gipskartonwände in zehn Einzelräume. Die Raumfolge setzte sich aus fünf breiteren, unbeleuchteten und fünf schmäleren, beleuchteten Räumen, die sich abwechselten, zusammen.", "Das Ungewöhnliche der größeren Räume bestand darin, dass sie sich aus der Maßstabsvergrößerung des innenliegenden Hohlraums einer Gipskarton-Trennwand ergaben. In Scale Scale Scale wurde dieser Zwischenraum zu einem raumfüllenden Ort aufgebläht, in dem man sich aufhalten konnte. Technische und funktionale Elemente wie Trägerkonstruktionen, Steckdosen oder Heizungen, die in tradierten Ausstellungskonzepten wie dem White Cube im Inneren der Wände versteckt sind, wurden in den vergrößerten Zwischenräumen bewusst sichtbar positioniert. An die Dunkelräume angrenzend, errichtete das Kollektiv schmale, weiß gestrichene Räume, die durch künstliches Licht erhellt wurden und sich aus der Maßstabsverkleinerung des eigentlichen Ausstellungsraums ergaben. Der ursprüngliche Ausstellungsort wurde dadurch in den Zwischenraum gedrängt, die Bühne hingegen dem sonst Unsichtbaren, dem Inwendigen gegeben.", "In dieser Umkehrung von Größenverhältnissen warfen YRD.Works Fragen zur Funktionsweise ästhetisierter Räume wie dem White Cube auf und integrierten die Besucher*innen in ihre verdrehte Inszenierung. Verschiedene simultane Blickachsen innerhalb der Installation ergaben ein multi-perspektivisches Bild, welches das bühnenartige Artifizielle von Ausstellungsräumen kritisch hinterfragte."], "gallery": [["Bilder/2016-scale-scale-scale/01.webp", 1500, 1000], ["Bilder/2016-scale-scale-scale/02.webp", 1499, 1000], ["Bilder/2016-scale-scale-scale/03.webp", 667, 1000], ["Bilder/2016-scale-scale-scale/04.webp", 1498, 1000], ["Bilder/2016-scale-scale-scale/05.webp", 1498, 1000], ["Bilder/2016-scale-scale-scale/06.webp", 667, 1000], ["Bilder/2016-scale-scale-scale/07.webp", 1542, 1000], ["Bilder/2016-scale-scale-scale/08.webp", 1500, 1000], ["Bilder/2016-scale-scale-scale/09.webp", 1500, 1000], ["Bilder/2016-scale-scale-scale/10.webp", 1500, 1000]], "text_en": ["In 2016, Scale Scale Scale, an expansive installation realised in collaboration with the artist collective D665, opened the second exhibition at the Kressmann-Halle in Offenbach. The work grew out of a joint theoretical engagement with the function and aesthetics of the exhibition spaces that YRD.Works had built a few months earlier. How do spaces created for art or theatre work? By what criteria are they dimensioned? And what effect do spatial conditions have on viewers?", "In Scale Scale Scale, YRD.Works developed an intervention that literally focused on the scale of the Kressmann-Halle. To do so, they divided the 160 m² hall, which they had built as an exhibition space a few months earlier, into ten individual rooms using temporary plasterboard walls. The sequence consisted of five wider, unlit rooms alternating with five narrower, lit ones.", "What was unusual about the larger rooms was that they resulted from scaling up the cavity inside a plasterboard partition. In Scale Scale Scale, this in-between space was inflated into a room-filling place in which one could spend time. Technical and functional elements such as support structures, sockets or radiators, which in traditional exhibition concepts like the white cube are hidden inside the walls, were deliberately placed in view in the enlarged cavities. Adjacent to the dark rooms, the collective built narrow, white-painted rooms lit by artificial light, which resulted from scaling down the actual exhibition space. The original exhibition space was thus pushed into the gap, while the stage was given to what is otherwise invisible, the inside.", "In this reversal of proportions, YRD.Works raised questions about how aestheticised spaces such as the white cube function and integrated visitors into their twisted staging. Various simultaneous sightlines within the installation produced a multi-perspective image that critically questioned the stage-like artificiality of exhibition spaces."], "fotos": "Gabriel Poblete · Simon Keckeisen"}, {"year": "2016", "title": "Kressmann-Halle", "jahr": "2016–2026", "ort": "Offenbach", "art": "Ausstellungsort", "desc": "Ausstellungsraum von YRD.Works im Offenbacher Hafen, 2016 bis 2026", "text": ["Die Kressmann-Halle war ein Ausstellungsraum, den YRD.Works im Sommer 2016 im Offenbacher Hafen eröffneten. Dafür hatte das Künstlerkollektiv eine ehemalige Montagehalle kernsaniert und in mehrmonatiger handwerklicher Arbeit in eine 160 m² große, professionelle Ausstellungshalle verwandelt. Bis 2026 zeigten YRD.Works dort in regelmäßigen Abständen zeitgenössische Kunst. Die Halle sollte einer jungen Kunstszene als Plattform dienen und den Austausch mit überregionalen Künstler*innen ermöglichen.", "Ausgestellt haben dort unter anderem Okka-Esther Hungerbühler, Nasan Tur, Sonja Yakovleva, Marcel Walldorf, Dauphine Klein, Tom Król und Marco Poblete. Neben den Ausstellungen gab es Performances. In der Halle entstanden außerdem eigene Arbeiten von YRD.Works: Scale Scale Scale (2016) mit dem Kollektiv D665, die 1. Offenbacher Seefestspiele (2017) im Außenbereich und der Pizzalieferdienst Not Not Pizza (2018) mit Eike König."], "gallery": [["Bilder/2016-kressmann-halle/01.webp", 1499, 1000], ["Bilder/2016-kressmann-halle/02.webp", 1695, 1000], ["Bilder/2016-kressmann-halle/03.webp", 1500, 1000], ["Bilder/2016-kressmann-halle/04.webp", 1500, 1000], ["Bilder/2016-kressmann-halle/05.webp", 1400, 1000], ["Bilder/2016-kressmann-halle/06.webp", 666, 1000], ["Bilder/2016-kressmann-halle/07.webp", 1496, 997]], "text_en": ["The Kressmann-Halle was an exhibition space that YRD.Works opened in Offenbach's harbour in summer 2016. For this, the artist collective had completely renovated a former assembly hall and, in several months of manual work, turned it into a professional exhibition hall of 160 m². Until 2026, YRD.Works showed contemporary art there at regular intervals. The hall was meant to serve a young art scene as a platform and to enable exchange with artists from beyond the region.", "Artists who exhibited there include Okka-Esther Hungerbühler, Nasan Tur, Sonja Yakovleva, Marcel Walldorf, Dauphine Klein, Tom Król and Marco Poblete. Alongside the exhibitions there were performances. The hall was also where some of YRD.Works' own works were made: Scale Scale Scale (2016) with the collective D665, the 1. Offenbacher Seefestspiele (2017) in the outdoor area and the pizza delivery service Not Not Pizza (2018) with Eike König."], "fotos": "Gabriel Poblete · Jessica Schäfer · Nasan Tur · Simon Keckeisen"}, {"year": "2015", "title": "Pool", "jahr": "2015–2022", "ort": "Offenbach", "art": "Skulptur / Veranstaltungsort", "desc": "Selbst betoniertes Schwimmbecken ohne Wasser als Open-Air-Ort für Techno im Offenbacher Hafen", "text": ["Pool ist eine begehbare Betonskulptur, die das Kulturkollektiv GetRich 2015 auf einer Brachfläche im Offenbacher Hafen errichtete. YRD.Works wirkten als Mitglieder des Kollektivs mit. Nach den Clubskulpturen Holzhausenstraße und Holzhausen suchte das Kollektiv nach einem Weg, Technoveranstaltungen im Freien zu realisieren, ohne die Nachbarschaft mit Lärm zu belasten. Gebaut wurde dafür ein Raum ohne Decke: ein selbst betoniertes, hellblau gestrichenes Schwimmbecken ohne Wasser, dessen Wände verhinderten, dass der Schall nach außen drang.", "Über mehrere Sommer diente Pool als Ort für Open-Air-Veranstaltungen der Techno- und Musikkultur. GetRich kooperierte dort mit überregionalen DJs wie Francesco Del Garda, Willow und Nu Guinea, mehrfach fanden Veranstaltungen mit den Kollektiven HardWorkSoftDrink, loof.tv und Re:boot Africa statt. Getanzt wurde im leeren Becken."], "gallery": [["Bilder/2015-pool/01.webp", 750, 1000], ["Bilder/2015-pool/02.webp", 1506, 1000], ["Bilder/2015-pool/03.webp", 1506, 1000], ["Bilder/2015-pool/04.webp", 1506, 1000], ["Bilder/2015-pool/05.webp", 1506, 1000], ["Bilder/2015-pool/06.webp", 1506, 1000], ["Bilder/2015-pool/07.webp", 664, 1000]], "text_en": ["Pool is a walk-in concrete sculpture built in 2015 by the cultural collective GetRich on a patch of wasteland in Offenbach's harbour. YRD.Works took part as members of the collective. After the club sculptures Holzhausenstraße and Holzhausen, the collective was looking for a way to hold techno events outdoors without burdening the neighbourhood with noise. To do this, they built a room without a ceiling: a self-cast swimming pool without water, painted light blue, whose walls prevented the sound from escaping.", "For several summers, Pool served as a venue for open-air events of techno and music culture. GetRich collaborated there with DJs from beyond the region such as Francesco Del Garda, Willow and Nu Guinea, and several events were held with the collectives HardWorkSoftDrink, loof.tv and Re:boot Africa. People danced in the empty pool."]}, {"year": "2015", "title": "Hafenmeisterei", "jahr": "2015–2022", "ort": "Offenbach", "art": "Zwischennutzung", "desc": "Inoffizielles Pop-up-Restaurant und Barort von GetRich im Haus des Hafenmeisters, 2015 bis 2022", "text": ["Die Hafenmeisterei entstand 2015 als inoffizielles Pop-up-Restaurant im leerstehenden Haus des Hafenmeisters, von dem aus einst der Betrieb des Offenbacher Hafens koordiniert wurde. Betrieben wurde sie vom Kulturkollektiv GetRich, in dem auch YRD.Works aktiv waren. Zuerst entwickelte das Kollektiv Gastraum und Küche, später kam eine Terrasse aus recyceltem Baustellenholz hinzu. Zu den Restaurantabenden meldeten sich die Gäste über einen E-Mail-Newsletter an, serviert wurden mehrere Gänge.", "Mit der Zeit wurden regelmäßige Barabende zur Institution, bei denen sich die Offenbacher Kulturszene traf. Im weiteren Sinn gehörten auch die Veranstaltungen im Pool zur Hafenmeisterei. Bis 2022 blieb sie ein versteckter, halböffentlicher Ort für inoffizielle Kulturangebote: Der Eingang lag hinter einer großen Plakatwand, und mit ihren Bäumen und verschiedenen Terrassen war die Hafenmeisterei von außen nicht einsehbar, ein Ort, den man in der Industriebrache nicht vermutet hätte."], "gallery": [["Bilder/2014-hafenmeisterei/01.webp", 1500, 1000], ["Bilder/2014-hafenmeisterei/02.webp", 1500, 1000], ["Bilder/2014-hafenmeisterei/03.webp", 1500, 1000], ["Bilder/2014-hafenmeisterei/04.webp", 1498, 1000], ["Bilder/2014-hafenmeisterei/05.webp", 1500, 1000], ["Bilder/2014-hafenmeisterei/06.webp", 747, 1000], ["Bilder/2014-hafenmeisterei/07.webp", 1339, 1000], ["Bilder/2014-hafenmeisterei/08.webp", 1333, 1000], ["Bilder/2014-hafenmeisterei/09.webp", 1280, 960], ["Bilder/2014-hafenmeisterei/10.webp", 1280, 720], ["Bilder/2014-hafenmeisterei/11.webp", 1333, 1000], ["Bilder/2014-hafenmeisterei/12.webp", 1500, 1000], ["Bilder/2014-hafenmeisterei/13.webp", 1500, 1000], ["Bilder/2014-hafenmeisterei/14.webp", 1280, 960]], "text_en": ["The Hafenmeisterei began in 2015 as an unofficial pop-up restaurant in the vacant harbourmaster's house, from which the operations of Offenbach's harbour were once coordinated. It was run by the cultural collective GetRich, in which YRD.Works were also active. The collective first developed the dining room and kitchen; later a terrace made of recycled construction-site timber was added. Guests signed up for the restaurant evenings via an email newsletter, and several courses were served.", "Over time, regular bar evenings became an institution where Offenbach's cultural scene met. In a broader sense, the events at Pool were also part of the Hafenmeisterei. Until 2022 it remained a hidden, semi-public place for unofficial cultural offerings: the entrance lay behind a large billboard, and with its trees and various terraces the Hafenmeisterei could not be seen from outside, a place no one would have expected in the industrial wasteland."]}, {"year": "2014", "title": "Pelican Bay", "jahr": "2014", "ort": "Offenbach", "art": "Rauminstallation", "desc": "Fitnessstudio aus selbst gegossenen Betonelementen im Atelierhaus einer Kunsthochschule", "text": ["Pelican Bay ist ein Fitnessstudio, das YRD.Works 2014 während ihres Studiums an der HfG Offenbach im Keller des Atelierhauses Geleitstraße 103 eingerichtet haben. Die Idee kam ihnen bei der Suche nach einem passenden Kraftsportangebot im Raum Frankfurt. Name und Gestaltung verweisen auf das Pelican Bay State Prison, ein Hochsicherheitsgefängnis in Kalifornien: In optischer Anlehnung an die Krafträume US-amerikanischer Gefängnisse wurden die Fitnessgeräte aus mehreren Tonnen Beton gegossen. Wie ein Gruppenraum im Gefängnis waren die Betonelemente vor allem funktional und ließen sich mit einem Hochdruckreiniger sauber halten."], "gallery": [["Bilder/2014-pelican-bay/01.webp", 1780, 1000], ["Bilder/2014-pelican-bay/02.webp", 1500, 1000], ["Bilder/2014-pelican-bay/03.webp", 1500, 1000], ["Bilder/2014-pelican-bay/04.webp", 1500, 1000]], "text_en": ["Pelican Bay is a gym that YRD.Works set up in 2014 while studying at the HfG Offenbach, in the basement of the studio building at Geleitstraße 103. The idea came to them while looking for a suitable strength-training option in the Frankfurt area. Name and design refer to Pelican Bay State Prison, a maximum-security prison in California: modelled visually on the weight rooms of US prisons, the fitness equipment was cast from several tonnes of concrete. Like a common room in a prison, the concrete elements were above all functional and could be kept clean with a pressure washer."], "fotos": "YRD.Works"}, {"year": "2014", "title": "Makoko", "jahr": "2014", "ort": "Offenbach", "art": "Lichtinstallation", "desc": "Schwimmende Lichtinstallation im Offenbacher Hafenbecken zur Luminale 2014", "text": ["Makoko ist eine schwimmende Lichtinstallation, die YRD.Works anlässlich der Luminale 2014 für das Offenbacher Hafenbecken entwickelten. Inhaltlich und ästhetisch bezogen sich die Leuchtkörper auf die Makoko Floating School, eine schwimmende Schule, die das Büro NLÉ um den Architekten Kunlé Adeyemi 2013 für die Gemeinde Makoko in Lagos, Nigeria, errichtet hatte. Deren A-Frame-Architektur übertrugen YRD.Works auf fünf Inseln aus transluzent bespannten Holzrahmen, die auf Schwimmkörpern im Wasser lagen. An dem Vorbild interessierten das Kollektiv neben dem Bauen auf dem Wasser die symbolische Funktion von Architektur und der fließende Übergang vom nutzbaren Bau zur Skulptur.", "Die Leuchtobjekte reagierten mit ihren Bewegungen und in ihrer räumlichen Anordnung auf Wind und Wetter. Eine Verankerung im Grund des Hafenbeckens verhinderte, dass sich die Formation vollständig auflöste. Das Licht der Inseln folgte einem programmierten Ablauf, den ein DMX-Controller von Land aus steuerte. Das Publikum verfolgte die Installation vom Ufer aus."], "gallery": [["Bilder/2014-makoko/01.webp", 1498, 1000], ["Bilder/2014-makoko/02.webp", 1498, 1000], ["Bilder/2014-makoko/03.webp", 1500, 1000], ["Bilder/2014-makoko/04.webp", 1498, 1000], ["Bilder/2014-makoko/05.webp", 1499, 1000]], "text_en": ["Makoko is a floating light installation that YRD.Works developed for the Offenbach harbour basin on the occasion of Luminale 2014. In content and aesthetics, the light objects referred to the Makoko Floating School, a floating school built in 2013 by the office NLÉ, led by architect Kunlé Adeyemi, for the Makoko community in Lagos, Nigeria. YRD.Works transferred its A-frame architecture to five islands of translucent-covered timber frames that floated on buoyancy bodies in the water. Besides building on water, what interested the collective in the model was the symbolic function of architecture and the fluid transition from usable building to sculpture.", "The light objects responded to wind and weather through their movements and their spatial arrangement. Anchoring them to the bottom of the harbour basin prevented the formation from dispersing completely. The light of the islands followed a programmed sequence, controlled from land via a DMX controller. The audience followed the installation from the shore."], "fotos": "Gabriel Poblete"}, {"year": "2014", "title": "Holzhausen", "jahr": "2014–2015", "ort": "Offenbach", "art": "Rauminstallation", "desc": "Zweite Clubskulptur von GetRich mit Empore und Terrasse, zwei Jahre in einer Offenbacher Lagerhalle", "text": ["Holzhausen ist die zweite Clubskulptur des Offenbacher Kulturkollektivs GetRich, zu dem auch YRD.Works gehörten. Sie entstand in Eigeninitiative als Zwischennutzung in derselben leerstehenden Lagerhalle wie ihre Vorgängerin Holzhausenstraße, die dafür abgerissen und deren Material wiederverwertet wurde. Weil sich GetRich die Halle in Kooperation mit dem ArtSpace RheinMain teilte, wuchs die Skulptur in die Höhe: Eine Empore lief an drei Seiten um die Tanzfläche herum und gab von oben den Blick auf das Geschehen frei. Dazu gehörte auch eine Terrasse im Außenbereich. Besonders interessierten YRD.Works bei diesem Projekt die Architektur und Gestaltung aus Grobspanplatten.", "Zwei Jahre lang konnte Holzhausen betrachtet und begangen werden. Für das Programm kooperierte das Kollektiv mit der regionalen Musik- und Technoszene, und über die Dauer des Projekts wurde Holzhausen zu einem Teil der Clubkultur im Rhein-Main-Gebiet. Mit dem Abriss der Lagerhalle endete auch Holzhausen."], "gallery": [["Bilder/2014-holzhausen/01.webp", 1500, 1000], ["Bilder/2014-holzhausen/02.webp", 1501, 1000], ["Bilder/2014-holzhausen/03.webp", 1500, 1000], ["Bilder/2014-holzhausen/04.webp", 1200, 800], ["Bilder/2014-holzhausen/05.webp", 1200, 800], ["Bilder/2014-holzhausen/06.webp", 1200, 800], ["Bilder/2014-holzhausen/07.webp", 1200, 800], ["Bilder/2014-holzhausen/08.webp", 1460, 1000]], "text_en": ["Holzhausen is the second club sculpture by the Offenbach cultural collective GetRich, to which YRD.Works also belonged. It was created on the collective's own initiative as a temporary use in the same vacant warehouse as its predecessor, Holzhausenstraße, which was demolished for it and whose material was reused. Because GetRich shared the hall in cooperation with ArtSpace RheinMain, the sculpture grew upwards: a gallery ran around the dance floor on three sides and offered a view of the action from above. An outdoor terrace was also part of it. What particularly interested YRD.Works in this project was architecture and design made of oriented strand board.", "For two years, Holzhausen could be viewed and entered. For the programme, the collective cooperated with the regional music and techno scene, and over the course of the project Holzhausen became part of the club culture of the Rhine-Main region. With the demolition of the warehouse, Holzhausen came to an end as well."], "fotos": "Jessica Schäfer"}, {"year": "2012", "title": "Holzhausenstraße", "jahr": "2012", "ort": "Offenbach", "art": "Rauminstallation", "desc": "Begehbare Clubskulptur aus Grobspanplatten in einer leerstehenden Lagerhalle", "text": ["Holzhausenstraße ist die erste von zwei begehbaren Clubskulpturen, die das Offenbacher Kulturkollektiv GetRich konzipiert und gebaut hat. YRD.Works waren Teil des Kollektivs. Die Rauminstallation bestand aus mehreren Tonnen Grobspanplatten und erstreckte sich über mehr als 300 m² in einer leerstehenden Lagerhalle. Eine Besonderheit waren die labyrinthartigen Gänge, in denen die Besucher*innen während der Musik-Performances das Gefühl für Raum und Zeit verlieren konnten.", "Nach den Raves, die GetRich zuvor organisiert hatte, war Holzhausenstraße der erste Ort, den das Kollektiv über einen längeren Zeitraum bespielte: An mehreren Nächten wurde in der Skulptur zu Techno getanzt. Gebaut wurde sie ohne Budget aus dem Freundeskreis heraus. Für die zweite Clubskulptur Holzhausen, ein neues Projekt in derselben Lagerhalle, wurde Holzhausenstraße abgerissen und ihr Material wiederverwertet."], "gallery": [["Bilder/2012-holzhausenstrasse/01.webp", 1499, 1000], ["Bilder/2012-holzhausenstrasse/02.webp", 1500, 1000], ["Bilder/2012-holzhausenstrasse/03.webp", 1500, 1000], ["Bilder/2012-holzhausenstrasse/04.webp", 1500, 1000], ["Bilder/2012-holzhausenstrasse/05.webp", 1499, 1000], ["Bilder/2012-holzhausenstrasse/06.webp", 1500, 1000], ["Bilder/2012-holzhausenstrasse/07.webp", 1500, 1000], ["Bilder/2012-holzhausenstrasse/08.webp", 1500, 1000]], "text_en": ["Holzhausenstraße is the first of two walk-in club sculptures conceived and built by the Offenbach cultural collective GetRich. YRD.Works were part of the collective. The spatial installation consisted of several tonnes of oriented strand board and extended over more than 300 m² in a vacant warehouse. A particular feature were the labyrinthine corridors in which visitors could lose their sense of space and time during the music performances.", "After the raves GetRich had previously organised, Holzhausenstraße was the first place the collective activated over a longer period: on several nights, people danced to techno inside the sculpture. It was built without a budget from within a circle of friends. For the second club sculpture, Holzhausen, a new project in the same warehouse, Holzhausenstraße was demolished and its material reused."], "fotos": "Lena Ditlmann"}];
var ABOUT={"title": "About", "year": "", "specs": [], "text": ["YRD.Works sind Yacin Boudalfa, Ruben Fischer und David Bausch, ein interdisziplinäres Künstlerkollektiv aus Offenbach am Main. Seit über zehn Jahren arbeiten sie an der Schnittstelle von Raum, Skulptur, Performance und sozialer Interaktion. Ihre Praxis verbindet künstlerische und architektonische Strategien mit performativen und partizipativen Ansätzen, um Räume zu schaffen, die nicht nur entworfen, sondern auch genutzt, aktiviert und gemeinschaftlich weiterentwickelt werden.", "Mit einer starken Verankerung im öffentlichen Raum und einem offenen Kunstbegriff als sozialem Prozess realisieren YRD.Works temporäre Installationen, performative Plattformen und experimentelle Raumkonzepte. Ihre Arbeiten hinterfragen konventionelle Ausstellungsformate und erforschen neue Formen der Teilhabe und des gemeinschaftlichen Engagements. Neben ihrer eigenen künstlerischen Praxis kuratieren sie Ausstellungsräume, kulturelle Zwischennutzungen und interdisziplinäre Veranstaltungen und schlagen dabei Brücken zwischen Kunst, Architektur und sozialem Austausch.", "Ihre Projekte entwickeln sich häufig in offenen, kollaborativen Prozessen und zeichnen sich durch die experimentelle Arbeit mit unterschiedlichen Materialien und Medien sowie durch die aktive Einbindung der Teilnehmenden aus."], "text_en": ["YRD.Works are Yacin Boudalfa, Ruben Fischer and David Bausch, an interdisciplinary artist collective from Offenbach, Germany, working for over ten years at the intersection of space, sculpture, performance and social interaction. Their practice merges artistic and architectural strategies with performative and participatory approaches to create spaces that are not only designed but also used, activated and collectively developed.", "With a strong foundation in public space and an open definition of art as a social process, YRD.Works realise temporary installations, performative platforms and experimental spatial concepts. Their work challenges conventional exhibition formats and explores new forms of participation and communal engagement. In addition to their own artistic practice, they curate exhibition spaces, cultural interim uses and interdisciplinary events, bridging art, architecture, and social exchange.", "Their projects often evolve through an open, collaborative process and are characterised by experimentation with different materials and media as well as the active involvement of participants."], "gallery": [["Bilder/about/01.jpg", 1498, 1000]]};
var YRD_Z=false;
var AUSWAHL=[{"key": "leerstand-und-soziale-raeume", "id": "fam-1", "titel": "Leerstand und soziale Räume", "titel_en": "Vacancy and Social Spaces", "text": "", "idx": [26, 27, 28, 31, 32]}, {"key": "kuenstlerische-rauminstallationen", "id": "fam-2", "titel": "Künstlerische Rauminstallationen", "titel_en": "Artistic Spatial Installations", "text": "", "idx": [1, 14, 16, 19, 22, 25]}, {"key": "interventionen-im-urbanen-und-laendlichen-raum", "id": "fam-3", "titel": "Interventionen im urbanen und ländlichen Raum", "titel_en": "Interventions in Urban and Rural Space", "text": "", "idx": [2, 5, 9, 11, 15, 17]}, {"key": "buehnen-plattformen-und-kuratorische-arbeit", "id": "fam-4", "titel": "Bühnen, Plattformen und kuratorische Arbeit", "titel_en": "Stages, Platforms and Curatorial Work", "text": "", "idx": [2, 17, 19, 20, 26]}, {"key": "auftragsarbeiten-und-institutionelle-kooperationen", "id": "fam-5", "titel": "Auftragsarbeiten und institutionelle Kooperationen", "titel_en": "Commissions and Institutional Collaborations", "text": "", "idx": [0, 3, 8, 13]}, {"key": "interdisziplinaeres-arbeiten-und-projektbezogenes-experimentieren", "id": "fam-6", "titel": "Interdisziplinäres Arbeiten und projektbezogenes Experimentieren", "titel_en": "Interdisciplinary Work and Project-Based Experimentation", "text": "", "idx": [7, 9, 10, 12, 18, 21]}, {"key": "soziale-projekte-und-partizipative-formate", "id": "fam-7", "titel": "Soziale Projekte und partizipative Formate", "titel_en": "Social Projects and Participatory Formats", "text": "", "idx": [5, 6, 10]}, {"key": "wissensvermittlung-und-temporaere-lernorte", "id": "fam-8", "titel": "Wissensvermittlung und temporäre Lernorte", "titel_en": "Knowledge Transfer and Temporary Places of Learning", "text": "", "idx": [0, 2, 8, 13]}];
